insert into public.guides(slug,audience,kind,title,description,levels,topic,goals,intro,body,summary,cover_url,pdf_url,review_note,status,sort_order) values
('gd-parent-library','parent','guide','دليل استخدام المكتبة التعليمية لأولياء الأمور','خطوات بسيطة لتصل إلى المحتوى المناسب لطفلك في مكتبة زاد وتستفيد منه: من اختيار القسم إلى التحميل والطباعة وتنظيم الجلسة.',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],'استخدام المكتبة',array['أن تعرف أقسام المكتبة وما يناسب كل قسم.','أن تصل إلى المحتوى المناسب لعمر طفلك أو صفه في دقائق.','أن تحمّل الملفات وتطبعها وتجهّز جلسة تعلّم قصيرة.']::text[],'مكتبة زاد فيها قصص وبطاقات وأنشطة وملخصات وأوراق وملفات للطباعة ووسائل تعليمية وتدريبات. كثرة المحتوى مفيدة، لكنها قد تربك الأسرة في البداية، لذلك نبدأ بخطة صغيرة: قسم واحد، نشاط واحد، جلسة قصيرة.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "حدّد عمر طفلك أو صفه", "x": "ابدأ بالسؤال: كم عمر طفلي، وفي أي صف هو؟ فالمحتوى مرتّب حسب العمر (من سنة إلى ٦ سنوات) وحسب الصف (من الأول إلى الرابع).", "ic": "x_board"}, {"h": "اختر القسم المناسب لهدفك", "x": "للقراءة والمتعة: القصص. للمفردات والتسمية: البطاقات. للتطبيق العملي: الأنشطة. للمراجعة: الملخصات والتدريبات. للشرح البصري: الوسائل التعليمية.", "ic": "i_books"}, {"h": "استعمل البحث والفلاتر", "x": "في أغلب الأقسام يمكنك تحديد العمر أو الصف والمادة، أو كتابة كلمة في شريط البحث مثل «الحروف» أو «الجمع».", "ic": "1f50d"}, {"h": "افتح المحتوى وعاينه أولًا", "x": "اقرأ العنوان والوصف وشاهد المعاينة قبل أن تحمّل أو تطبع، لتتأكد أنه يناسب طفلك.", "ic": "1f441"}, {"h": "حمّل الملف أو اطبعه", "x": "اختر «تحميل» لحفظ ملف PDF، أو «طباعة» للطباعة مباشرة. اطبع بحجم ١٠٠٪ على ورق A4 دون تصغير.", "ic": "1f5d3"}, {"h": "جهّز جلسة قصيرة وابدأ", "x": "خصّص من ١٠ إلى ٢٠ دقيقة بحسب عمر الطفل، وجهّز الأقلام والألوان قبل أن يجلس.", "ic": "23f3"}]}, {"t": "h", "x": "أقسام المكتبة وماذا تجد فيها"}, {"t": "table", "head": ["القسم", "ماذا تجد فيه", "متى أستعمله؟"], "rows": [["القصص", "قصص قصيرة بصور وأسئلة فهم", "قبل النوم أو في وقت الهدوء"], ["البطاقات", "بطاقات صور وكلمات ومفاهيم", "للتسمية والمطابقة والألعاب السريعة"], ["الأنشطة", "أنشطة منزلية وأوراق عمل للتنفيذ", "في جلسة التعلم اليومية"], ["الملخصات والتدريبات", "ملخصات دروس وأسئلة مراجعة", "قبل الاختبار أو بعد الدرس"], ["الوسائل التعليمية", "خرائط ذهنية وملصقات ولوحات وأنشطة قابلة للطباعة", "للشرح البصري وتثبيت المعلومة"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "أم لطفلة عمرها ٥ سنوات تريد تدريبها على الحروف: تفتح قسم البطاقات وتختار عمر ٥ سنوات، ثم تحمّل بطاقات الحروف وتطبعها، وتلعب مع طفلتها ١٠ دقائق بمطابقة الحرف بالصورة، ثم تقرأ قصة قصيرة قبل النوم."}, {"t": "tips", "title": "نصائح عملية", "items": ["ابدأ بقسم واحد لمدة أسبوع قبل أن تجرّب أقسامًا أخرى.", "احفظ الملفات المفضلة في مجلد واحد على هاتفك لتصل إليها بسرعة.", "اجعل الطفل يشارك في اختيار النشاط ضمن خيارين تحددهما أنت.", "لا تُكثر الطباعة؛ اطبع ما ستستعمله هذا الأسبوع فقط."]}]$j$::jsonb,array['حدّد العمر أو الصف ثم القسم ثم النشاط.','عاين المحتوى قبل التحميل أو الطباعة.','اطبع بحجم ١٠٠٪ على ورق A4.','جلسة قصيرة منتظمة أفضل من جلسة طويلة نادرة.']::text[],'images/guides/gd-parent-library/cover.webp','files/guides/gd-parent-library.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',10),
('gd-teacher-resources','teacher','guide','دليل استخدام الموارد التعليمية للمعلم','كيف تبحث في مكتبة زاد وتنتقي الموارد وتدمجها في خطتك الأسبوعية وتحضّرها للصف.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'استخدام الموارد',array['أن تصل إلى المورد المناسب لهدف الدرس بسرعة.','أن تقيّم جودة المورد وملاءمته لصفك.','أن تدمج الموارد في خطة أسبوعية منظمة.']::text[],'الموارد الجاهزة توفّر وقت التحضير، لكنها لا تغني عن تحديد الهدف. أفضل استعمال لها أن تبدأ من هدف الدرس، ثم تختار المورد الذي يخدمه، لا أن تبدأ من المورد ثم تبحث له عن درس.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "حدّد هدف الدرس بجملة", "x": "مثال: يقرأ الطالب كلمات فيها لام شمسية. الهدف يحدد نوع المورد.", "ic": "i_target"}, {"h": "ابحث بالصف والمادة والموضوع", "x": "استعمل فلاتر الصف والمادة وشريط البحث، ثم قارن بين مورد وآخر.", "ic": "1f50d"}, {"h": "قيّم المورد قبل اعتماده", "x": "هل المعلومة صحيحة؟ هل المستوى مناسب؟ هل التعليمات واضحة؟ هل يحتاج تعديلًا؟", "ic": "1f9d0"}, {"h": "حدّد دوره في الحصة", "x": "تمهيد، شرح، تدريب، مراجعة، أم تقويم؟ لكل مورد دور واحد رئيس.", "ic": "1f5d3"}, {"h": "جهّز النسخ والأدوات", "x": "اطبع بحجم ١٠٠٪ وجهّز عددًا يكفي الطلاب، أو اعرض الملف على الشاشة.", "ic": "1f5a8"}, {"h": "دوّن ملاحظات بعد التنفيذ", "x": "ما الذي نجح؟ وما الذي يحتاج تعديلًا؟ احتفظ بالملاحظة للمرة القادمة.", "ic": "1f4dd"}]}, {"t": "table", "head": ["هدف الحصة", "المورد الأنسب"], "rows": [["تمهيد لموضوع جديد", "قصة أو ملصق أو خريطة ذهنية"], ["شرح مفهوم", "عرض تقديمي أو رسم توضيحي"], ["تدريب فردي", "ورقة عمل أو نشاط للطباعة"], ["تدريب جماعي", "بطاقات أو لوحة صفية"], ["مراجعة وتقويم", "ملخص وتدريبات وبنك أسئلة"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "معلم الصف الثاني يدرّس «الجمل الاسمية والفعلية»: يبدأ بعرض تقديمي قصير للشرح (٥ دقائق)، ثم ورقة تصنيف جمل في مجموعات، وتنتهي الحصة بثلاثة أسئلة مراجعة سريعة من بنك الأسئلة."}, {"t": "tips", "title": "نصائح عملية", "items": ["لا تستعمل أكثر من موردين في الحصة الواحدة.", "اجعل في خطتك دائمًا نشاطًا بديلًا قصيرًا.", "شارك الطلاب في اختيار بعض الأنشطة لرفع الدافعية.", "عدّل صياغة الأسئلة لتناسب أسلوبك وبيئة طلابك."]}]$j$::jsonb,array['ابدأ بهدف الدرس لا بالمورد.','قيّم المورد قبل اعتماده.','لكل مورد دور واحد في الحصة.','دوّن ملاحظات التنفيذ للمرة القادمة.']::text[],'images/guides/gd-teacher-resources/cover.webp','files/guides/gd-teacher-resources.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',110),
('gd-child-library','child','guide','أستعمل مكتبة زاد','دليل مصوّر يعلّم الطفل كيف يفتح المكتبة ويختار القسم ويبدأ.',array['a4','a5','a6','g1','g2']::text[],'استخدام المكتبة',array['أتعلّم كيف أفعل ذلك وحدي أو مع أمي أو أبي أو معلمتي.']::text[],'دليل مصوّر قصير. اقرأ الخطوات مع شخص كبير، ثم جرّب بنفسك!',$j$[{"t": "steps", "title": "", "items": [{"h": "أفتح مكتبة زاد", "x": "مع شخص كبير أفتح الموقع وأرى الأقسام.", "ic": "i_books"}, {"h": "أختار ما أحب", "x": "قصص؟ بطاقات؟ أنشطة؟ ألعاب؟ أضغط على القسم.", "ic": "1f446"}, {"h": "أبحث بالصورة والكلمة", "x": "أكتب كلمة مثل «قطة» أو أختار عمري.", "ic": "1f50d"}, {"h": "أفتح وأنظر", "x": "أنظر إلى الصور وأقرأ العنوان.", "ic": "1f441"}, {"h": "أرجع عندما أنتهي", "x": "أضغط زر الرجوع وأختار شيئًا آخر.", "ic": "1f3e0"}]}, {"t": "ex", "title": "تذكّر", "x": "إذا لم أجد ما أريد، أطلب من أمي أو أبي أن يساعدني في البحث."}]$j$::jsonb,array['أطبّق الخطوات واحدة واحدة.','أطلب المساعدة عندما أحتاج.','أفرح بما أنجزته!']::text[],'images/guides/gd-child-library/cover.webp','files/guides/gd-child-library.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',210),
('gd-age-3-4','parent','age','دليل التعلم من ٣ إلى ٤ سنوات','إرشادات للتعلم باللعب في عمر ٣–٤: الألوان والأشكال والمطابقة والقصص القصيرة والتلوين.',array['a3','a4']::text[],'حسب العمر والمرحلة',array['أن تعرف ما يناسب طفلك من أنشطة.','أن تنظّم جلسات قصيرة ممتعة.','أن تدعم لغته وتفكيره بأسئلة مفتوحة.']::text[],'في هذا العمر يكثر الطفل من الأسئلة، ويحب التقليد واللعب الخيالي. التعلم الأفضل يأتي من نشاط ممتع قصير يربط ما يتعلمه بالواقع.',$j$[{"t": "h", "x": "ماذا يميّز هذه المرحلة؟"}, {"t": "table", "head": ["الجانب", "ما تلاحظه غالبًا"], "rows": [["اللغة", "يتكلم بجمل قصيرة ويسأل: لماذا؟"], ["التفكير", "يصنّف ويطابق بسيطًا ويفهم قصصًا قصيرة"], ["الحركة", "يقص بصعوبة ويمسك قلمًا بكامل يده تقريبًا"], ["الانتباه", "١٠ إلى ١٥ دقيقة مع النشاط الممتع"]]}, {"t": "h", "x": "أنشطة ومحتوى مناسب"}, {"t": "table", "head": ["النشاط", "لماذا يناسب؟"], "rows": [["بطاقات الألوان والأشكال", "تنمّي التمييز والتصنيف"], ["أنشطة مطابقة وفرز بسيطة", "تنمّي المنطق"], ["قصص قصيرة جدًا بصور", "تنمّي المفردات والخيال"], ["تلوين ورسم حر", "يدرّب العضلات الدقيقة"], ["ألعاب الأرقام ١ إلى ٥", "عدّ بالأشياء الحقيقية"]]}, {"t": "h", "x": "جلسة نموذجية"}, {"t": "steps", "title": "", "items": [{"h": "ابدأ بأغنية أو لعبة سريعة", "x": "دقيقتان لجذب الانتباه."}, {"h": "قدّم نشاطًا واحدًا", "x": "مثل فرز البطاقات حسب اللون أو الشكل."}, {"h": "اطرح سؤالًا مفتوحًا", "x": "لماذا وضعتها هنا؟ ماذا ترى؟"}, {"h": "دعه يجرّب بنفسه", "x": "ساعده بتلميح لا بحل جاهز."}, {"h": "اختم بقصة قصيرة أو تلوين", "x": "هدوء ثم انتقال إلى نشاط حر."}]}, {"t": "tips", "title": "ما الذي أتجنبه؟", "items": ["أوراق العمل الطويلة والكتابة المكثفة.", "تصحيح كل خطأ فورًا.", "المقارنة بالأقران.", "جلسات تتجاوز ١٥ دقيقة."]}, {"t": "ex", "title": "مثال تطبيقي", "x": "مع طفل (٤ سنوات): ٦ بطاقات أشكال وألوان. يفرزها حسب اللون في ٣ صناديق، ثم تسأله أمه: كيف عرفت؟ وبعدها يلوّن شكلًا من اختياره."}]$j$::jsonb,array['اللعب أساس التعلم.','جلسة ١٠ إلى ١٥ دقيقة بنشاط واحد.','أسئلة مفتوحة وتلميحات صغيرة.','لا ضغط ولا كتابة مكثفة.']::text[],'images/guides/gd-age-3-4/cover.webp','files/guides/gd-age-3-4.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',320),
('gd-parent-age','parent','guide','دليل اختيار المحتوى المناسب لعمر الطفل','كيف تعرف إن كان النشاط أو القصة أو الورقة مناسبة لعمر طفلك، وما مدة الجلسة والأسلوب الأنسب لكل مرحلة.',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],'اختيار المحتوى',array['أن تفرّق بين ما يناسب كل مرحلة عمرية.','أن تعرف علامات أن المحتوى صعب أو سهل جدًا.','أن تعدّل النشاط ليناسب قدرات طفلك.']::text[],'الأطفال يتفاوتون في سرعة نموّهم، والعمر مؤشر وليس قاعدة صارمة. المحتوى المناسب هو الذي يكون أصعب قليلًا مما يعرفه الطفل، فيشعر بالتحدي دون أن يشعر بالعجز.',$j$[{"t": "h", "x": "ما يناسب كل مرحلة"}, {"t": "table", "head": ["المرحلة", "نوع المحتوى الأنسب", "مدة الجلسة التقريبية"], "rows": [["سنة إلى سنتين", "بطاقات صور كبيرة، تسمية الأشياء، أصوات الحيوانات، أغانٍ وحركات", "٥ إلى ١٠ دقائق"], ["٣ إلى ٤ سنوات", "ألوان وأشكال، مطابقة، تصنيف بسيط، قصص قصيرة جدًا، تلوين", "١٠ إلى ١٥ دقيقة"], ["٥ إلى ٦ سنوات", "الحروف والأعداد، تتبّع الخطوط، متاهات سهلة، قصص بأسئلة بسيطة", "١٥ إلى ٢٠ دقيقة"], ["الصف الأول والثاني", "قراءة جمل قصيرة، جمع وطرح، أوراق عمل قصيرة، خرائط ذهنية مبسطة", "٢٠ إلى ٣٠ دقيقة"], ["الصف الثالث والرابع", "قراءة نصوص، ضرب وقسمة، كتابة فقرة، ملخصات وتدريبات", "٣٠ إلى ٤٠ دقيقة"]]}, {"t": "h", "x": "كيف تتأكد من مناسبة المحتوى؟"}, {"t": "steps", "title": "", "items": [{"h": "اقرأ العمر أو الصف المكتوب على البطاقة", "x": "كل محتوى في المكتبة مكتوب عليه الفئة المناسبة له."}, {"h": "جرّب النشاط بنفسك دقيقة", "x": "إن احتجت لشرح طويل فالنشاط غالبًا أصعب من اللازم لطفل صغير."}, {"h": "راقب أول ٥ دقائق", "x": "الانتباه والمحاولة علامتان جيدتان. أما التململ السريع أو الرفض فعلامة على أن النشاط صعب أو سهل أو طويل."}, {"h": "عدّل بدل أن تتخلى", "x": "اجعل النشاط أقصر، أو شارك الطفل في أول سؤال، أو انتقل إلى فئة عمرية أقل أو أعلى حسب الحاجة."}]}, {"t": "tips", "title": "نصائح عملية", "items": ["إن أنجز الطفل النشاط بسهولة تامة فانتقل إلى مستوى أعلى.", "إن تعثّر في أغلب الأسئلة فعد خطوة إلى الوراء بنشاط أسهل في الموضوع نفسه.", "لا تقارن طفلك بأقرانه؛ قارنه بنفسه قبل أسبوع.", "اختلاف الطفل عن الجدول لا يعني وجود مشكلة؛ وإن قلقت فاسأل معلمه أو مختصًا."]}, {"t": "ex", "title": "مثال تطبيقي", "x": "طفل عمره ٦ سنوات يتعثّر في ورقة جمع حتى ٢٠. تنزل أمه إلى ورقة جمع حتى ١٠ بالأصابع والأشياء الحقيقية أسبوعًا، ثم تعود إلى الورقة الأولى وهو يحلّها بثقة."}]$j$::jsonb,array['العمر مؤشر وليس قاعدة صارمة.','المحتوى المناسب فيه تحدٍّ بسيط دون إحباط.','راقب أول ٥ دقائق وعدّل النشاط.','قارن الطفل بنفسه لا بالآخرين.']::text[],'images/guides/gd-parent-age/cover.webp','files/guides/gd-parent-age.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',20),
('gd-parent-home','parent','guide','دليل مساعدة الطفل على التعلم في المنزل','أفكار عملية لتهيئة المكان والوقت والأسلوب حتى يتعلم طفلك في المنزل بمتعة ودون ضغط.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'التعلم المنزلي',array['أن تهيّئ ركنًا ووقتًا مناسبين للتعلم.','أن تتعلم أسلوب المرافقة دون أن تحل مكان الطفل.','أن تحوّل المواقف اليومية إلى فرص تعلّم.']::text[],'التعلم في المنزل لا يعني أن تتحول البيوت إلى مدارس. يكفي أن يشعر الطفل أن التعلم ممتع وأنك بجانبه، وأن يرى القراءة والعدّ والسؤال جزءًا من حياة الأسرة.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "اختر ركنًا ثابتًا وهادئًا", "x": "طاولة صغيرة وإضاءة جيدة وأدوات في متناول اليد (أقلام، ألوان، ورق). أبعد الهاتف والتلفاز أثناء الجلسة.", "ic": "i_desk"}, {"h": "اختر وقتًا ثابتًا قصيرًا", "x": "وقت يكون فيه الطفل مرتاحًا وغير جائع أو متعبًا. ١٠ إلى ٣٠ دقيقة بحسب العمر، يوميًا أو في أيام محددة.", "ic": "23f0"}, {"h": "ابدأ بشيء يحبه", "x": "ابدأ بلعبة أو قصة، ثم انتقل إلى النشاط المطلوب. البداية الممتعة تفتح شهية الطفل للتعلم.", "ic": "1f604"}, {"h": "اشرح بخطوة واحدة في كل مرة", "x": "قل له ما المطلوب بجملة قصيرة، وأره مثالًا واحدًا، ثم دعه يجرّب.", "ic": "1f446"}, {"h": "رافق ولا تُنجز بدلًا عنه", "x": "إذا تعثر فاسأله: ماذا تظن؟ جرّب مرة أخرى. وقدّم تلميحًا صغيرًا بدل الإجابة.", "ic": "1f914"}, {"h": "اختم بتشجيع وتلخيص", "x": "اسأله: ماذا تعلمنا اليوم؟ وامدح جهده، ثم أنهِ الجلسة وهو يشعر بالنجاح.", "ic": "1f3c6"}]}, {"t": "h", "x": "تحويل الحياة اليومية إلى تعلّم"}, {"t": "table", "head": ["الموقف اليومي", "ما يتعلمه الطفل"], "rows": [["ترتيب المشتريات", "التصنيف والعدّ ومقارنة الأحجام"], ["إعداد وجبة أو عصير", "الأعداد والمقادير والمفردات الجديدة"], ["المشي في الشارع", "قراءة اللافتات والألوان والأشكال"], ["وقت قبل النوم", "الاستماع والمفردات والتخيّل عبر قصة"], ["سقي نبتة", "الملاحظة والمسؤولية ومفهوم النمو"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "في المطبخ يطلب الأب من ابنه (٦ سنوات): أحضر لي ٣ ملاعق ثم ملعقة أخرى، كم صارت؟ وعندما ينتهون يسأله: ما أول شيء فعلناه؟ ثم ماذا؟ بهذا يتعلم العدّ والجمع وترتيب الأحداث."}, {"t": "tips", "title": "نصائح عملية", "items": ["اجعل الجلسات قصيرة ومنتظمة، فهي أنفع من جلسة طويلة متعبة.", "قبل الجلسة بيوم، اختر نشاطًا واحدًا وجهّز أدواته.", "إذا غضب الطفل أو تعب فأوقف النشاط وعد إليه لاحقًا بهدوء.", "اجعل للطفل خيارًا بين نشاطين لتزيد دافعيته."]}]$j$::jsonb,array['ركن هادئ ووقت ثابت وجلسة قصيرة.','ابدأ بشيء ممتع ثم انتقل للمطلوب.','رافق الطفل ولا تحل بدلًا عنه.','اختم بتشجيع وتلخيص لما تعلّمه.']::text[],'images/guides/gd-parent-home/cover.webp','files/guides/gd-parent-home.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',30),
('gd-parent-worksheets','parent','guide','دليل استخدام أوراق العمل مع الطفل','كيف تختار ورقة العمل وتجهّزها وتشرحها وتراجع إجابات طفلك دون أن تتحول إلى واجب ثقيل.',array['a5','a6','g1','g2','g3','g4']::text[],'أوراق العمل',array['أن تختار ورقة تناسب مستوى الطفل.','أن تجهّز الورقة وتشرحها بأسلوب مبسّط.','أن تراجع الإجابات وتحوّل الأخطاء إلى فرصة للتعلم.']::text[],'ورقة العمل أداة تطبيق: يتدرب فيها الطفل على ما تعلّمه. تنجح عندما تكون قصيرة ومناسبة وبعد شرح أو لعب، لا عندما تكون عقابًا أو مهمة تُفرض.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "حدّد المهارة التي تريد تدريبها", "x": "مهارة واحدة في الورقة الواحدة: مثل الجمع حتى ١٠ أو تتبّع الحرف «ب»."}, {"h": "اختر الورقة المناسبة", "x": "اقرأ الفئة المكتوبة وانظر إن كان عدد الأسئلة مناسبًا لوقت طفلك."}, {"h": "جهّز الأدوات", "x": "قلم رصاص وممحاة وألوان، وطاولة نظيفة. اطبع بحجم ١٠٠٪."}, {"h": "اشرح السؤال الأول معه", "x": "حلّا السؤال الأول معًا، ثم دعه يكمل. إن كانت الورقة طويلة قسّمها على يومين."}, {"h": "راجع الإجابات معه", "x": "اسأله: كيف عرفت؟ ثم صحّح الأخطاء بهدوء. اطلب منه أن يشرح طريقة حله بنفسه."}, {"h": "سجّل وانتقل", "x": "اكتب ملاحظة قصيرة عن المهارة وإن كانت تحتاج إعادة، وكافئه على الجهد."}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "ورقة «جمع وطرح حتى ٢٠» لطفل في الصف الأول: يحلّ ٦ مسائل ثم يرتاح، ويكمل الباقي في اليوم التالي. عند المراجعة تلاحظ الأم أن الأخطاء كلها في الطرح، فتخصص الأسبوع التالي لتدريبات الطرح بأشياء ملموسة."}, {"t": "tips", "title": "نصائح عملية", "items": ["لا تُجبر الطفل على إنهاء ورقة طويلة في جلسة واحدة.", "أعطه الوقت الكافي؛ السرعة ليست هدفًا في البداية.", "اجعل الأخطاء موضوع حوار لا موضع لوم.", "نوّع بين ورقة تُكتب وورقة تُلوّن أو تُقصّ أو تُلصق."]}]$j$::jsonb,array['مهارة واحدة في كل ورقة.','اشرح السؤال الأول وشاركه.','راجع الإجابات واسأله كيف حلّ.','قسّم الورقة الطويلة على أكثر من يوم.']::text[],'images/guides/gd-parent-worksheets/cover.webp','files/guides/gd-parent-worksheets.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',40),
('gd-parent-stories','parent','guide','دليل قراءة القصص مع الطفل','كيف تجعل القصة وقتًا ممتعًا ينمّي اللغة والخيال والانتباه، مع أسئلة قبل القراءة وأثناءها وبعدها.',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],'القصص',array['أن تحوّل القراءة إلى لحظة حوار ممتعة.','أن تطرح أسئلة مناسبة لعمر الطفل.','أن تربط القصة بحياة الطفل ومفرداته.']::text[],'القصة ليست للتسلية فقط؛ هي مدرسة صغيرة للمفردات والخيال والتعاطف. وقيمتها تزيد عندما نقرأ معًا ونتحدث عنها بدل أن نكتفي بقراءتها بصوت مسموع.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "اختر القصة بحسب العمر", "x": "للصغار: قصص قصيرة بصور كبيرة وجمل بسيطة. للأكبر: قصص فيها حدث ومشكلة وحل.", "ic": "i_book"}, {"h": "اجلس بقرب الطفل وجهّز الجو", "x": "مكان هادئ وإضاءة مريحة، وأطفئ الشاشات. اجعل الطفل يمسك الكتاب أو يقلّب الصفحات.", "ic": "1f9f8"}, {"h": "قبل القراءة: توقّع", "x": "اعرض الغلاف واسأل: عمّ تتحدث القصة برأيك؟ من الشخصية الرئيسة؟", "ic": "1f914"}, {"h": "أثناء القراءة: توقف قليلًا", "x": "غيّر نبرة صوتك للشخصيات، واسأل عن الصورة: ماذا ترى؟ ماذا سيحدث بعد ذلك؟", "ic": "1f5e3"}, {"h": "بعد القراءة: حاور", "x": "اسأل: من أحببت؟ لماذا؟ ماذا كنت ستفعل مكانه؟ ثم اطلب منه أن يعيد القصة بكلماته.", "ic": "1f4ac"}, {"h": "كرّر القصة المفضلة", "x": "التكرار مفيد؛ فالطفل في كل مرة يلاحظ تفصيلة جديدة ويتعلم كلمات أكثر.", "ic": "1f501"}]}, {"t": "h", "x": "أسئلة مناسبة لكل عمر"}, {"t": "table", "head": ["العمر", "نوع الأسئلة", "مثال"], "rows": [["سنة إلى سنتين", "أين؟ ما هذا؟ ما صوته؟", "أين القطة؟ ماذا تقول القطة؟"], ["٣ إلى ٤ سنوات", "من؟ ماذا فعل؟ ما لونه؟", "ماذا فعل الأرنب؟"], ["٥ إلى ٦ سنوات", "لماذا؟ ماذا بعد؟ هل أعجبك؟", "لماذا حزن الولد؟"], ["الصف الأول إلى الرابع", "ما الدرس؟ ماذا تتوقع؟ ما رأيك؟", "ماذا تعلمت من تصرّف الشخصية؟"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "بعد قراءة قصة عن الأرنب والسلحفاة يسأل الأب ابنته (٧ سنوات): لماذا فاز من مشى بثبات؟ هل حدث لك موقف مشابه؟ ثم تطلب منه أن ترسم أحب مشهد."}, {"t": "tips", "title": "نصائح عملية", "items": ["١٠ إلى ١٥ دقيقة كافية في الأعمار الصغيرة.", "اجعل القصة قبل النوم عادة ثابتة.", "لا تُحوّل القصة إلى اختبار؛ يكفي سؤال أو سؤالان.", "دع الطفل يختار القصة أحيانًا."]}]$j$::jsonb,array['اقرأ معًا لا بالنيابة عنه.','اسأل قبل القراءة وأثناءها وبعدها.','كرّر القصص المحبوبة.','اجعل القصة عادة يومية قصيرة.']::text[],'images/guides/gd-parent-stories/cover.webp','files/guides/gd-parent-stories.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',50),
('gd-parent-cards','parent','guide','دليل استخدام البطاقات التعليمية مع الطفل','ألعاب سهلة بالبطاقات لتعليم الأسماء والحروف والأعداد والمفاهيم، مع طريقة التدرج من السهل إلى الصعب.',array['a2','a3','a4','a5','a6','g1','g2']::text[],'البطاقات التعليمية',array['أن تحضّر البطاقات وتحفظها بشكل عملي.','أن تلعب بها ألعابًا متدرجة تناسب العمر.','أن تراجع المفردات بطريقة ممتعة.']::text[],'البطاقات من أبسط الوسائل وأكثرها نفعًا: صورة وكلمة وفكرة واحدة. وتنجح عندما تُستعمل في لعب قصير متنوع لا في تكرار ممل.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "اطبع واقصّ وغلّف", "x": "اطبع البطاقات على ورق متين إن أمكن، وقصّها بهدوء، ويمكن تغليفها لتدوم. اجمعها في علبة صغيرة.", "ic": "1f4cb"}, {"h": "ابدأ بـ ٣ إلى ٥ بطاقات فقط", "x": "اعرضها وسمِّها وردّدها مع الطفل. الزيادة الكبيرة تُربك الصغار.", "ic": "1f590"}, {"h": "العب لعبة سريعة", "x": "أخفِ بطاقة، أعرض بطاقتين وقل: أين …؟ أو اجعل الطفل يختار بطاقة ويسمّيها.", "ic": "1f3ae"}, {"h": "أضف بطاقات جديدة بالتدريج", "x": "بعد أن يتقن الطفل بطاقات، أضف بطاقتين جديدتين واخلطها بالقديمة.", "ic": "1f9e9"}, {"h": "راجع على فترات", "x": "كرّر المراجعة بعد يوم ثم بعد أيام، فالتكرار المتباعد يثبّت المعلومة.", "ic": "1f501"}]}, {"t": "h", "x": "أفكار ألعاب بالبطاقات"}, {"t": "table", "head": ["اللعبة", "كيف تُلعب؟", "ما تنمّيه"], "rows": [["أين البطاقة؟", "أنشر ٤ بطاقات واطلب واحدة", "الانتباه والتعرّف"], ["بطاقة مفقودة", "أخفِ واحدة وسل: ماذا اختفى؟", "الذاكرة"], ["المطابقة", "ضع البطاقة بجانب ما يشبهها (لون، شكل، حرف)", "الملاحظة والتصنيف"], ["من يقول الكلمة؟", "يسمّي كل لاعب بطاقة بالدور", "المفردات والنطق"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "مع طفل عمره ٣ سنوات: أربع بطاقات (تفاحة، موزة، قطة، كلب). نسمّيها ونصنّفها إلى «نأكلها» و«حيوانات» في صندوقين، ثم نضيف بطاقة جديدة كل يومين."}, {"t": "tips", "title": "نصائح عملية", "items": ["اجعل اللعب قصيرًا وانهِه والطفل متحمس.", "نطقك الواضح للكلمة هو أفضل نموذج.", "لا تُجبر الطفل على الإجابة؛ شجّعه بالتجربة والمحاولة."]}]$j$::jsonb,array['٣ إلى ٥ بطاقات في البداية.','اللعب أهم من الحفظ.','أضف بطاقات جديدة بالتدريج.','راجع بعد يوم ثم بعد أيام.']::text[],'images/guides/gd-parent-cards/cover.webp','files/guides/gd-parent-cards.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',60),
('gd-parent-progress','parent','guide','دليل متابعة تقدم الطفل','طريقة بسيطة لتسجيل ما أنجزه الطفل وملاحظة نقاط قوته وما يحتاج تعزيزًا، دون ضغط أو مقارنة.',array['a4','a5','a6','g1','g2','g3','g4']::text[],'المتابعة',array['أن تحدد مهارات واضحة تتابعها.','أن تسجّل التقدم بوسيلة بسيطة.','أن تستعمل الملاحظات لتعديل الخطة.']::text[],'المتابعة الجيدة ليست جمع علامات؛ هي أن ترى ما يتحسّن وما يحتاج وقتًا. وتكفي عبارات قصيرة منتظمة لتعطيك صورة أوضح من الانطباع العابر.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "اختر ٣ مهارات فقط في الشهر", "x": "مثل: تتبّع الحروف، الجمع حتى ١٠، قراءة كلمات قصيرة. الكثرة تشتت المتابعة."}, {"h": "حدّد مستوى بسيطًا لكل مهارة", "x": "لا يعرفها بعد / يحاول بمساعدة / ينجزها وحده."}, {"h": "سجّل بعد كل جلسة في سطر", "x": "التاريخ والنشاط وجملة: ماذا نجح؟ وماذا احتاج؟ يمكنك استعمال نموذج المتابعة الجاهز في المكتبة."}, {"h": "راجع كل أسبوعين", "x": "اجلس ٥ دقائق وانظر: ما التقدم؟ ما الذي لم يتحرك؟"}, {"h": "عدّل الخطة", "x": "إذا ثبتت مهارة فانتقل لما بعدها، وإن تعثّرت فاختر نشاطًا أسهل أو غيّر الأسلوب."}]}, {"t": "table", "head": ["المهارة", "قبل أسبوعين", "الآن", "الخطوة التالية"], "rows": [["تتبّع الحرف «ب»", "بمساعدة", "وحده", "حرف «ت»"], ["الجمع حتى ١٠", "لا يعرفها", "بمساعدة", "تمارين بأشياء ملموسة"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "تلاحظ أم أن ابنها يقرأ الكلمات القصيرة بسرعة لكنه يتعثّر في الكلمات التي فيها شدّة. تضيف جلسة قصيرة أسبوعيًا على كلمات فيها شدّة، وتسجّل التحسّن بعد أسبوعين."}, {"t": "tips", "title": "نصائح عملية", "items": ["اكتب الإيجابيات أولًا ثم نقطة تحتاج عملًا.", "شارك الطفل في التتبع بنجمة أو علامة يضعها هو.", "لا تُظهر خيبتك أمام الطفل؛ المتابعة ليست امتحانًا له.", "إن لاحظت تعثرًا مستمرًا شهورًا في مهارة أساسية فاستشر المعلم أو مختصًا."]}]$j$::jsonb,array['٣ مهارات في الشهر فقط.','سجّل بجمل قصيرة وبانتظام.','راجع كل أسبوعين وعدّل الخطة.','المتابعة لدعم الطفل لا للمحاسبة.']::text[],'images/guides/gd-parent-progress/cover.webp','files/guides/gd-parent-progress.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',70),
('gd-parent-time','parent','guide','دليل تنظيم وقت التعلم واللعب','كيف توازن في يوم طفلك بين التعلم واللعب والراحة، مع جدول بسيط مناسب لكل عمر.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'تنظيم الوقت',array['أن تضع روتينًا يوميًا مرنًا لطفلك.','أن توازن بين التعلم واللعب والراحة.','أن تتعامل مع الشاشات والمشتتات بخطة واضحة.']::text[],'الأطفال يتعلمون باللعب أكثر مما نتصور، والتعلم المنظم يحتاج مكانًا في اليوم بين الراحة والنشاط الحر. الروتين الواضح يمنح الطفل الأمان ويقلل الجدال اليومي.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "ارسم يومًا تقريبيًا مع الطفل", "x": "اكتب أو ارسم محطات اليوم: استيقاظ، وجبة، لعب، جلسة تعلم، راحة، نوم. شارك الطفل في الرسم."}, {"h": "ضع جلسة التعلم في وقت نشاطه", "x": "لا تضعها وهو جائع أو نعسان. بعد وجبة خفيفة أو راحة قصيرة غالبًا أنسب."}, {"h": "اجعل اللعب الحر محميًا", "x": "اللعب الحر ليس مضيعة وقت؛ فيه يتعلم الطفل حل المشكلات والتعاون والخيال."}, {"h": "ضع حدودًا للشاشات", "x": "حدّد وقتًا ثابتًا ومدة معروفة سلفًا، وأبعد الشاشة عن وقت الوجبات والنوم."}, {"h": "راجع الجدول أسبوعيًا", "x": "ما نجح فأبقِه، وما سبّب توترًا فعدّله."}]}, {"t": "table", "head": ["العمر", "مثال يوم تقريبي (تعلّم)", "ملاحظة"], "rows": [["٣ إلى ٤ سنوات", "١٠ دقائق نشاط + قصة قصيرة + لعب حر طويل", "التعلم داخل اللعب"], ["٥ إلى ٦ سنوات", "١٥ إلى ٢٠ دقيقة نشاط + قصة + لعب", "جلسة واحدة يوميًا تكفي"], ["الصف الأول والثاني", "٢٠ إلى ٣٠ دقيقة مراجعة وواجب + قراءة ١٠ دقائق", "راحة بعد المدرسة قبل الواجب"], ["الصف الثالث والرابع", "٣٠ إلى ٤٠ دقيقة واجب ومراجعة + قراءة حرة", "جدول أسبوعي مكتوب"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "أسرة تضع الواجب والمراجعة بعد العصر بنصف ساعة راحة، ثم لعبًا حرًا، ثم عشاء وقصة قبل النوم. وتعلّق جدولًا مصورًا على الثلاجة ويضع الطفل نجمة بعد كل محطة."}, {"t": "tips", "title": "نصائح عملية", "items": ["الثبات في الروتين أهم من الصرامة فيه.", "امنح الطفل خيارًا ضمن الجدول (أي نشاط أولًا؟).", "اترك فترات فراغ بلا برنامج لتشجيع الإبداع.", "ضع وقت النوم قبل كل شيء؛ النوم الكافي يحسّن التعلم."]}]$j$::jsonb,array['جدول بسيط مرن يشارك فيه الطفل.','جلسة التعلم في وقت نشاطه.','احمِ اللعب الحر ونظّم الشاشات.','النوم الكافي أولوية.']::text[],'images/guides/gd-parent-time/cover.webp','files/guides/gd-parent-time.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',80),
('gd-parent-motivation','parent','guide','دليل تشجيع الطفل وتحفيزه','كيف تشجّع طفلك بالكلمة والفعل لتنمّي حبه للتعلم وثقته بنفسه، دون رشوة أو مقارنة.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'التحفيز',array['أن تمدح الجهد والمحاولة لا النتيجة فقط.','أن تستعمل مكافآت بسيطة معنوية.','أن تتعامل مع الإحباط والفشل بإيجابية.']::text[],'الطفل يتحفّز عندما يشعر أن جهده مرئي وأن الخطأ جزء طبيعي من التعلم. التشجيع الصادق المحدّد أقوى من العبارات العامة، والمكافآت المعنوية أبقى أثرًا من الحلوى.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "امدح الجهد والأسلوب", "x": "قل: أعجبني أنك حاولت أكثر من مرة، بدل: أنت ذكي. فالجهد يمكن تكراره، أما «الذكاء» فيجعل الطفل يخشى الخطأ.", "ic": "1f44f"}, {"h": "كن محدّدًا", "x": "قل: رسمت الحرف على السطر بدقة. فالمدح المحدّد يخبر الطفل بما يكرره.", "ic": "1f3af"}, {"h": "اجعل الأهداف صغيرة", "x": "هدف اليوم: ٣ أسطر لا الصفحة كلها. النجاح المتكرر الصغير يبني الثقة.", "ic": "2b50"}, {"h": "استعمل مكافآت معنوية", "x": "لوحة نجوم، اختيار القصة الليلة، وقت لعب مع أحد الوالدين، شهادة صغيرة.", "ic": "1f3c6"}, {"h": "تعامل مع الخطأ بهدوء", "x": "قل: لنرَ ما حدث وكيف نصلحه. الخطأ يعني أن الدماغ يتعلم.", "ic": "1f4aa"}]}, {"t": "table", "head": ["بدل أن تقول", "قل"], "rows": [["أنت ذكي جدًا!", "تعبت في الحل وكنت صبورًا."], ["كم أنت سريع!", "راجعت إجابتك قبل أن تسلّمها، أحسنت."], ["لماذا أخطأت؟", "لنرَ الخطوة التي نحتاج أن نعدلها."], ["أخوك أفضل منك", "لقد تحسنت عن الأسبوع الماضي."]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "طفلة في الصف الثاني تتعثر في القراءة. تحدد أمها هدفًا: قراءة ٥ كلمات جديدة يوميًا، وتضع نجمة على لوحة الأسبوع. في نهاية الأسبوع تختار البنت القصة الليلة، فتشعر أن جهدها له قيمة."}, {"t": "tips", "title": "نصائح عملية", "items": ["تجنّب ربط الحب أو القبول بالنتائج.", "قلّل من المكافآت المادية الكبيرة حتى لا تصير هي الهدف.", "اعترف بمشاعر الإحباط: أعرف أنه صعب، وسنجرّب معًا.", "كن قدوة: دع الطفل يراك تقرأ وتتعلم."]}]$j$::jsonb,array['امدح الجهد والمحاولة بعبارات محددة.','أهداف صغيرة ونجاحات متكررة.','مكافآت معنوية بسيطة.','الخطأ فرصة للتعلم.']::text[],'images/guides/gd-parent-motivation/cover.webp','files/guides/gd-parent-motivation.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',90),
('gd-teacher-worksheets','teacher','guide','دليل توظيف أوراق العمل في الدروس','متى تستعمل ورقة العمل في الحصة، وكيف تقدّمها وتديرها وتصحّحها بطريقة تخدم التعلم لا الإنجاز الشكلي.',array['g1','g2','g3','g4']::text[],'أوراق العمل',array['أن تحدد موقع الورقة في بنية الحصة.','أن تدير وقت الورقة وأسئلة الطلاب.','أن تستفيد من النتائج في التخطيط التالي.']::text[],'ورقة العمل أداة تدريب، وتصبح مفيدة حين تأتي بعد الشرح مباشرة وتكون قصيرة وواضحة وفيها تدرّج في الصعوبة، ثم تُراجَع بسرعة لتحوّل الخطأ إلى درس.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "اختر ورقة تتدرج في الصعوبة", "x": "ابدأ بأسئلة مباشرة ثم أسئلة تتطلب تفكيرًا. الورقة التي كلها سهلة أو كلها صعبة قليلة الفائدة."}, {"h": "قدّم الورقة بدقيقتين", "x": "اشرح المطلوب بمثال واحد محلول، وبيّن الزمن المتاح."}, {"h": "دع الطلاب يعملون ثم تجوّل", "x": "تنقّل بين المقاعد وسجّل في ذهنك أكثر الأخطاء تكرارًا بدل أن تجيب على كل سؤال فرديًا."}, {"h": "راجع بسرعة", "x": "اعرض الإجابات على السبورة أو الشاشة واطلب من طالب أن يشرح طريقته."}, {"h": "حلّل الأخطاء", "x": "اجمع الأخطاء الشائعة في قائمة قصيرة وخطّط لنشاط علاجي قصير."}]}, {"t": "table", "head": ["موقع الورقة", "متى؟", "الهدف"], "rows": [["بداية الحصة", "قبل الدرس", "استدعاء ما سبق"], ["وسط الحصة", "بعد الشرح مباشرة", "تطبيق موجّه"], ["نهاية الحصة", "آخر ١٠ دقائق", "تقويم سريع"], ["واجب", "بعد الحصة", "ترسيخ مستقل"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "بعد درس الجمع بالحمل يوزّع المعلم ورقة بـ ٨ مسائل: ٣ مباشرة، ٣ بحمل، ٢ مسألة كلامية. يستغرق العمل ١٠ دقائق، ويراجع المسألة الرابعة على السبورة لأن أغلب الأخطاء فيها، ثم يعطي الطلاب المتعثرين مسألتين إضافيتين."}, {"t": "tips", "title": "نصائح عملية", "items": ["لا تثقل الواجب المنزلي بأوراق طويلة.", "نوّع بين أوراق تُكتب وأخرى تُقص وتُلصق أو تُلوّن.", "اجعل للورقة هدفًا مكتوبًا في أعلاها.", "احتفظ بالأوراق المصححة لقياس تقدم الطلاب."]}]$j$::jsonb,array['الورقة بعد الشرح لا قبله.','قدّم المطلوب بمثال محلول.','جمّع الأخطاء الشائعة وعالجها.','اجعل الواجب قصيرًا ومفيدًا.']::text[],'images/guides/gd-teacher-worksheets/cover.webp','files/guides/gd-teacher-worksheets.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',120),
('gd-teacher-cards','teacher','guide','دليل استخدام البطاقات التعليمية في الصف','أفكار منظمة لأنشطة البطاقات في الصف: مفردات ومطابقة ومحطات تعلّم قصيرة، مع إدارة وقتها وطلابها.',array['a3','a4','a5','a6','g1','g2','g3']::text[],'البطاقات التعليمية',array['أن تخطّط نشاط بطاقات قصيرًا ومنظمًا.','أن تدير المجموعات والوقت بسهولة.','أن تتدرج بالنشاط من البسيط إلى المركّب.']::text[],'البطاقات مرنة وسريعة التحضير، وتصلح لأنشطة فردية وثنائية وجماعية. وتعمل أفضل عندما يكون لكل نشاط قاعدة واضحة وزمن قصير وهدف محدد.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "حدّد الهدف والمجموعة", "x": "مفردات جديدة؟ مراجعة؟ تصنيف؟ ثم حدّد عدد البطاقات: ٦ إلى ١٢ لكل مجموعة غالبًا."}, {"h": "جهّز مجموعات البطاقات", "x": "اطبع وقصّ وغلّف، ورتّب كل مجموعة في ظرف أو علبة مع ورقة قواعد صغيرة."}, {"h": "اشرح القاعدة بمثال", "x": "اعرض لعبة تجريبية سريعة مع طالبين أمام الصف قبل أن يبدأ الجميع."}, {"h": "شغّل المحطات أو الثنائيات", "x": "قسّم الصف إلى مجموعات صغيرة، وحدّد زمنًا ٥ إلى ٧ دقائق ثم بدّل البطاقات أو المجموعات."}, {"h": "اختم بسؤال تلخيصي", "x": "اطلب من كل مجموعة أن تذكر كلمة أو معلومة تعلّمتها اليوم."}]}, {"t": "table", "head": ["النشاط", "الفكرة", "المهارة"], "rows": [["مطابقة", "صورة مع كلمة أو حرف مع صوت", "التعرف والربط"], ["فرز", "تصنيف البطاقات إلى فئتين أو ثلاث", "التصنيف"], ["ما المفقود؟", "يُخفى بطاقة ويحدد الطلاب المفقودة", "الذاكرة"], ["بطاقة الخروج", "بطاقة تُسلَّم عند الخروج", "تقويم سريع"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "في حصة المفردات للصف الأول: ٨ بطاقات حيوانات. تقسّم المعلمة الصف إلى أربع ثنائيات، تلعب كل ثنائية «المفقود» ٥ دقائق، ثم تتبادل الثنائيات مجموعات البطاقات."}, {"t": "tips", "title": "نصائح عملية", "items": ["اكتب رقمًا على ظهر كل مجموعة لتسهّل إعادتها كاملة.", "خصّص طالبًا مسؤولًا عن توزيع المجموعات وجمعها.", "لا تجعل النشاط تنافسيًا كثيرًا مع الصغار.", "اجعل البطاقات مصدرًا للحوار لا للحفظ فقط."]}]$j$::jsonb,array['٦ إلى ١٢ بطاقة في كل مجموعة.','قاعدة واضحة وزمن قصير.','جرّب اللعبة أمام الصف أولًا.','اختم بسؤال تلخيصي.']::text[],'images/guides/gd-teacher-cards/cover.webp','files/guides/gd-teacher-cards.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',130),
('gd-teacher-stories','teacher','guide','دليل توظيف القصص في التعليم','كيف تستعمل القصة في الصف لتنمية اللغة والفهم والقيم، مع خطة قراءة بثلاث مراحل وأسئلة متدرجة.',array['a4','a5','a6','g1','g2','g3','g4']::text[],'القصص',array['أن تخطّط حصة قصة بثلاث مراحل: قبل وأثناء وبعد القراءة.','أن تطرح أسئلة تنمّي الفهم والتفكير.','أن تربط القصة بنشاط تعبير أو رسم.']::text[],'القصة تجذب الانتباه وتقدّم المعلومة داخل سياق إنساني يسهل تذكره. وتنجح في الصف حين يكون لها هدف لغوي أو قيمي واضح، لا مجرد وقت قراءة.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "اختر قصة تناسب الهدف والمستوى", "x": "اقرأها سلفًا، وحدّد ٣ كلمات جديدة أو فكرة رئيسة."}, {"h": "قبل القراءة", "x": "اعرض الغلاف أو الصورة وشجّع التوقّع: عمّ تظن أن القصة تتحدث؟"}, {"h": "أثناء القراءة", "x": "توقف عند مواضع مناسبة: ماذا سيحدث بعد؟ لماذا فعل ذلك؟ وفسّر الكلمات الجديدة بالصور أو التمثيل."}, {"h": "بعد القراءة", "x": "اسأل أسئلة فهم (من؟ أين؟ متى؟) ثم أسئلة تفكير (لماذا؟ ماذا لو؟)."}, {"h": "نشاط ختامي", "x": "رسم مشهد، أو إعادة سرد بالترتيب، أو كتابة جملة عن الدرس المستفاد."}]}, {"t": "table", "head": ["مستوى الأسئلة", "مثال"], "rows": [["مباشر (يوجد في النص)", "من ساعد الأرنب؟"], ["استنتاجي (بين السطور)", "كيف عرفت أنه كان حزينًا؟"], ["تقويمي (رأي الطالب)", "هل تصرّف الأرنب تصرفًا صحيحًا؟ لماذا؟"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "قصة «الأرنب والسلحفاة» للصف الثاني: قبل القراءة يتوقع الطلاب من سيفوز. وبعد القراءة يعيدون ترتيب ٤ صور للأحداث، ثم يكتبون جملة: «أتعلّم أن …»."}, {"t": "tips", "title": "نصائح عملية", "items": ["خصّص ١٠ إلى ١٥ دقيقة للقصة وباقي الوقت للنشاط.", "اجعل الطلاب يقرؤون بالتناوب أو بالأدوار.", "اربط القصة بقيمة أو مهارة وردت في المنهج دون أن تُثقل الحصة.", "اطلب من الطلاب اقتراح نهاية بديلة للقصة."]}]$j$::jsonb,array['حدّد هدفًا لغويًا أو قيميًا للقصة.','قبل وأثناء وبعد القراءة.','تدرّج في مستوى الأسئلة.','اختم بنشاط تعبير أو رسم.']::text[],'images/guides/gd-teacher-stories/cover.webp','files/guides/gd-teacher-stories.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',140),
('gd-teacher-activities','teacher','guide','دليل إعداد الأنشطة الصفية','خطوات تصميم نشاط صفي قصير ومنظم: هدف واضح وأدوات بسيطة وتعليمات مرتبة وتقويم سريع.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'الأنشطة الصفية',array['أن تصمّم نشاطًا قصيرًا بهدف قابل للقياس.','أن تجهّز الأدوات وتنظّم الوقت والمجموعات.','أن تقيّم النشاط وتحسّنه.']::text[],'النشاط الجيد قصير وهادف وواضح. ولا يحتاج أدوات معقدة؛ يكفي أن يعرف الطلاب ماذا يفعلون ولماذا، وأن يخرجوا بشيء يمكنك أن تلاحظه أو تقيسه.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "اكتب الهدف بصيغة سلوك", "x": "مثل: يصنّف الطالب ٨ أشياء إلى فئتين. وليس: يفهم التصنيف."}, {"h": "اختر الصيغة المناسبة", "x": "فردي أم ثنائي أم جماعي؟ ورقة أم بطاقات أم حركة؟ بحسب الهدف والعمر."}, {"h": "جهّز الأدوات والتعليمات", "x": "اكتب التعليمات في ٣ خطوات على الأكثر، وجهّز الأدوات في صناديق صغيرة."}, {"h": "حدّد الزمن والمجموعات", "x": "نشاط من ١٠ إلى ٢٠ دقيقة، ومجموعات من ٢ إلى ٤ طلاب، وطالب مسؤول في كل مجموعة."}, {"h": "نفّذ وراقب", "x": "تجوّل ولاحظ، وقدّم تلميحات صغيرة، ودوّن ما تلاحظه."}, {"h": "اختم بتقويم قصير", "x": "سؤالان شفويان أو بطاقة خروج، ثم اسأل نفسك: هل تحقق الهدف؟"}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "هدف: يرتّب الطالب أيام الأسبوع. النشاط: بطاقات الأيام تُوزَّع على مجموعات من ٤، ويرتّبونها في ٣ دقائق، ثم تُقارن المجموعات ترتيبها، وتنتهي الحصة بسؤال: ما اليوم الذي يأتي بعد الثلاثاء؟"}, {"t": "tips", "title": "نصائح عملية", "items": ["جرّب النشاط بنفسك قبل الحصة للتأكد من الزمن.", "احتفظ بنشاط بديل جاهز إن انتهى الطلاب مبكرًا.", "اجعل الأدوار واضحة: من يكتب؟ من يقرأ؟ من يعرض؟", "قلّل الكلام واترك الوقت للنشاط."]}]$j$::jsonb,array['هدف بصيغة سلوك قابل للملاحظة.','تعليمات من ٣ خطوات.','زمن ومجموعات وأدوار واضحة.','تقويم قصير في النهاية.']::text[],'images/guides/gd-teacher-activities/cover.webp','files/guides/gd-teacher-activities.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',150),
('gd-teacher-media','teacher','guide','دليل استخدام الوسائل التعليمية','متى تعرض الخريطة الذهنية أو الملصق أو العرض أو اللوحة، وكيف تدمج الوسيلة في الشرح دون أن تتحول إلى زينة.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'الوسائل التعليمية',array['أن تختار الوسيلة المناسبة للفكرة.','أن تعرضها بأسلوب يجذب الانتباه.','أن تحوّلها إلى مرجع يعود إليه الطلاب.']::text[],'الوسيلة التعليمية تساعد على الفهم حين تشرح فكرة واحدة بوضوح. وإذا زاد فيها النص أو الألوان أو التفاصيل فقدت أثرها. اجعلها مرجعًا حيًا تعود إليه في الحصة لا لوحة تُعلَّق وتُنسى.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "حدّد الفكرة التي تريد توضيحها", "x": "فكرة واحدة لكل وسيلة: دورة حياة؟ تصنيف؟ قاعدة؟ خطوات؟"}, {"h": "اختر النوع المناسب", "x": "الخريطة الذهنية لربط المفاهيم، والملصق لتثبيت قاعدة، والجدول للمقارنة، والعرض للشرح المتسلسل، واللوحة للمتابعة اليومية."}, {"h": "اعرض الوسيلة وفسّرها", "x": "اعرضها واطلب من الطلاب وصف ما يرونه قبل أن تشرح."}, {"h": "اربطها بنشاط", "x": "اطلب من الطلاب إكمال خريطة ناقصة أو إيجاد المعلومة في الملصق."}, {"h": "علّقها وارجع إليها", "x": "علّق الوسيلة في مكان مرئي وأشِر إليها في الحصص اللاحقة."}]}, {"t": "table", "head": ["الوسيلة", "الأنسب لـ", "نصيحة"], "rows": [["خريطة ذهنية", "ربط الأفكار وتلخيص وحدة", "اطلب من الطلاب إضافة فرع"], ["ملصق", "قاعدة أو معلومة مرجعية", "ضعه عند مستوى نظر الطلاب"], ["عرض تقديمي", "شرح متسلسل", "شريحة واحدة لكل فكرة"], ["لوحة صفية", "متابعة يومية (طقس، مسؤوليات)", "اجعل الطلاب يحدّثونها"], ["رسم توضيحي أو إنفوجرافيك", "عملية أو دورة", "اطلب إعادة رسمها"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "بعد دروس الفصول والطقس، يعلّق المعلم «لوحة الطقس اليومي» ويكلّف طالبًا كل يوم بتحديثها، ثم يسأل في بداية الحصة: ماذا يتغيّر في الطقس خلال الأسبوع؟"}, {"t": "tips", "title": "نصائح عملية", "items": ["لا تعلّق أكثر من ٣ وسائل في الجدار نفسه.", "غيّر الوسائل بحسب الوحدة لتبقى حيّة.", "يمكن للطلاب صناعة نسختهم من الوسيلة لتثبيت التعلم.", "احتفظ بنسخة مطبوعة بالأبيض والأسود لتوفير الحبر عند الحاجة."]}]$j$::jsonb,array['فكرة واحدة لكل وسيلة.','اطلب من الطلاب وصفها قبل الشرح.','اربطها بنشاط وارجع إليها.','لا تُكثر الوسائل في مكان واحد.']::text[],'images/guides/gd-teacher-media/cover.webp','files/guides/gd-teacher-media.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',160),
('gd-teacher-review','teacher','guide','دليل إعداد المراجعات والتدريبات','كيف تخطّط حصة مراجعة فعّالة وتختار أسئلة التدريب وتوزّع المراجعة على أيام بدل تكديسها قبل الاختبار.',array['g1','g2','g3','g4']::text[],'المراجعة والتدريب',array['أن تخطّط مراجعة متباعدة وفعالة.','أن تختار تدريبات متنوعة ومتدرجة.','أن تستعمل نتائج التدريب لتوجيه المراجعة.']::text[],'المراجعة الفعالة لا تعني إعادة الشرح كله. هي استدعاء ما تعلّمه الطالب بأسئلة وأنشطة قصيرة، موزعة على أيام، تركّز على الأجزاء الضعيفة.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "حدّد عناصر الوحدة", "x": "اكتب ٥ إلى ٨ مفاهيم أو مهارات رئيسة في الوحدة."}, {"h": "اختبر الطلاب قبل أن تراجع", "x": "تدريب قصير ١٠ أسئلة يكشف ما يحتاج مراجعة فعلًا."}, {"h": "راجع بالتركيز على الضعف", "x": "اقضِ وقتك على الأجزاء التي أخطأ فيها أكثر الطلاب."}, {"h": "نوّع التدريبات", "x": "أسئلة اختيار، إكمال، تصنيف، شرح بكلمات الطالب، ومسائل تطبيقية."}, {"h": "وزّع على أيام", "x": "٢٠ دقيقة في ٤ أيام أفضل من ساعتين في ليلة واحدة."}]}, {"t": "table", "head": ["اليوم", "نشاط المراجعة"], "rows": [["١", "اختبار قصير تشخيصي + تصحيح جماعي"], ["٢", "مراجعة المفاهيم الأضعف بالخرائط والبطاقات"], ["٣", "ورقة تدريب متنوعة"], ["٤", "اختبار قصير ختامي وتأمل: ماذا تحسّن؟"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "قبل اختبار وحدة الضرب في الصف الثالث: يطلب المعلم ١٠ مسائل بلا مراجعة، فيكتشف أن أكثر الأخطاء في جدول ٦ و٧ و٨. يخصص حصتين لهذه الجداول بالبطاقات والألعاب، ثم يعيد اختبارًا قصيرًا فيرتفع الأداء."}, {"t": "tips", "title": "نصائح عملية", "items": ["اطلب من الطلاب أن يصنعوا أسئلة لزملائهم.", "استعمل بنك الأسئلة لتنويع التدريب.", "اجعل التدريب قصيرًا ومتكررًا.", "خصّص دقائق لتصحيح الأخطاء مع الطالب لا لحذفها فقط."]}]$j$::jsonb,array['ابدأ باختبار تشخيصي قصير.','ركّز على نقاط الضعف.','نوّع الأسئلة.','وزّع المراجعة على أيام.']::text[],'images/guides/gd-teacher-review/cover.webp','files/guides/gd-teacher-review.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',170),
('gd-teacher-skills','teacher','guide','دليل متابعة المهارات التعليمية','نموذج مبسّط لمتابعة مهارات الطلاب الأساسية بملاحظات قصيرة، لتعرف من يحتاج دعمًا ومن يحتاج إثراء.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'متابعة المهارات',array['أن تحدد المهارات الأساسية التي تتابعها.','أن تسجل الملاحظات بطريقة سريعة وعملية.','أن تستعمل الملاحظات لتشكيل مجموعات الدعم والإثراء.']::text[],'المتابعة الجيدة تسبق التقويم الرسمي: تسجّل ما يلاحظه المعلم أثناء العمل لتتحرك مبكرًا. وسجل بسيط يومي أفضل من تقرير مفصل متأخر.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "اختر ٣ إلى ٥ مهارات للفصل", "x": "مثل: قراءة كلمات قصيرة، كتابة جملة، الجمع حتى ٢٠."}, {"h": "ضع مستويات بسيطة", "x": "يحتاج دعمًا / يتقدّم / متمكّن. وعرّف كل مستوى بجملة."}, {"h": "سجّل أثناء العمل", "x": "استعمل جدولًا واحدًا لكل صف، وسجّل ملاحظتين أو ثلاثًا كل يوم."}, {"h": "كوّن مجموعات مرنة", "x": "طلاب «يحتاج دعمًا» مجموعة لتدريب إضافي، و«متمكّن» مجموعة لنشاط إثرائي، وتتغير المجموعات بحسب المهارة."}, {"h": "أخبر الأسرة بإيجاز", "x": "أرسل ملاحظة قصيرة: ما الذي تحسّن؟ وما الذي يمكن للأسرة أن تفعله؟"}]}, {"t": "table", "head": ["الطالب", "المهارة", "المستوى", "ملاحظة"], "rows": [["س", "قراءة كلمات قصيرة", "يتقدّم", "يتعثر في الكلمات ذات الشدة"], ["ص", "الجمع حتى ٢٠", "متمكّن", "جاهز لمسائل كلامية"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "بعد أسبوعين يلاحظ معلم الصف الأول أن ٥ طلاب يتعثرون في تمييز «ب» و«ت». يكوّن مجموعة مصغرة ٧ دقائق يوميًا بالبطاقات، ويعيد الملاحظة بعد أسبوع."}, {"t": "tips", "title": "نصائح عملية", "items": ["استعمل رموزًا لتسريع التسجيل (✓، ~، ✗).", "لا تتابع كل شيء؛ ركّز على الأهم.", "اجعل المتابعة سرية ومحترمة لخصوصية الطلاب.", "احتفظ بأمثلة من أعمال الطلاب لتوثيق التقدم."]}]$j$::jsonb,array['٣ إلى ٥ مهارات فقط.','مستويات بسيطة وملاحظات قصيرة.','مجموعات دعم وإثراء مرنة.','تواصل موجز مع الأسرة.']::text[],'images/guides/gd-teacher-skills/cover.webp','files/guides/gd-teacher-skills.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',180),
('gd-teacher-styles','teacher','guide','دليل تنويع أساليب التعلم في الصف','طرق عملية لتنويع الأنشطة بين البصري والسمعي والحركي واللعبي حتى يجد كل طالب ما يناسبه.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'أساليب التعلم',array['أن تنوّع الأنشطة في الحصة الواحدة.','أن تراعي الفروق الفردية.','أن تتجنب الاعتماد على أسلوب واحد.']::text[],'الطلاب يتعلمون بطرق مختلفة، وتنوّع الأنشطة يزيد من فرص وصول المعلومة للجميع. والتنويع ليس تصنيف الطلاب في أنماط ثابتة، بل تقديم الفكرة الواحدة بأكثر من طريقة.',$j$[{"t": "h", "x": "الخطوات العملية"}, {"t": "steps", "title": "", "items": [{"h": "قدّم الفكرة بصيغتين على الأقل", "x": "مثلًا: شرح شفهي + صورة أو خريطة ذهنية."}, {"h": "أضف حركة قصيرة", "x": "نشاط وقوف أو ترتيب بطاقات على الأرض أو تمثيل بالأجسام."}, {"h": "أتح خيارات في الإنجاز", "x": "يمكن للطالب أن يرسم أو يكتب أو يشرح شفهيًا ليبيّن ما فهمه."}, {"h": "نوّع التجميع", "x": "فردي، ثنائي، مجموعة، ثم عرض أمام الصف."}, {"h": "اسأل الطلاب ما الذي ساعدهم", "x": "سؤال قصير في النهاية يعطيك معلومة لتصميم الحصة التالية."}]}, {"t": "table", "head": ["الأسلوب", "أمثلة من المكتبة"], "rows": [["بصري", "ملصقات، خرائط ذهنية، رسوم توضيحية"], ["سمعي", "قصص مقروءة، أغانٍ، نقاش"], ["حركي", "بطاقات للفرز والمطابقة، ألعاب تمثيل"], ["كتابي/تطبيقي", "أوراق عمل، أنشطة للطباعة"], ["لعبي", "ألعاب وأنشطة جماعية"]]}, {"t": "ex", "title": "مثال تطبيقي", "x": "في درس «الفصول الأربعة»: لوحة فصول للمشاهدة، قصة قصيرة للاستماع، ثم يقف الطلاب ليمثلوا حركة كل فصل، وأخيرًا يرسم كل طالب فصله المفضل ويكتب جملة."}, {"t": "tips", "title": "نصائح عملية", "items": ["لا تجعل الحصة تبديلًا متسارعًا للأنشطة؛ ٣ أنشطة تكفي.", "خطّط الانتقال بين الأنشطة بإشارة واضحة.", "ابدأ بالأنشطة الحركية للصغار عند ملاحظة تعب.", "اجمع عمل الطلاب المتنوع في ملف لرؤية التقدم."]}]$j$::jsonb,array['قدّم الفكرة بأكثر من طريقة.','أضف حركة قصيرة.','أتح خيارات في الإنجاز.','اسأل الطلاب ما الذي ساعدهم.']::text[],'images/guides/gd-teacher-styles/cover.webp','files/guides/gd-teacher-styles.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',190),
('gd-child-activity','child','guide','أختار النشاط المناسب لي','دليل مصوّر يساعد الطفل على اختيار نشاط يناسب عمره ومزاجه.',array['a4','a5','a6','g1','g2']::text[],'اختيار النشاط',array['أتعلّم كيف أفعل ذلك وحدي أو مع أمي أو أبي أو معلمتي.']::text[],'دليل مصوّر قصير. اقرأ الخطوات مع شخص كبير، ثم جرّب بنفسك!',$j$[{"t": "steps", "title": "", "items": [{"h": "أنظر إلى عمري", "x": "أبحث عن النشاط المكتوب عليه عمري أو صفي.", "ic": "1f9d2"}, {"h": "أسأل نفسي: ماذا أريد؟", "x": "ألوّن؟ أقصّ؟ أحلّ لغزًا؟ أسمع قصة؟", "ic": "1f914"}, {"h": "أجرّب دقيقة", "x": "إذا كان سهلًا جدًا أطلب أصعب منه، وإذا كان صعبًا أطلب أسهل.", "ic": "23f3"}, {"h": "أستعين بأحد الكبار", "x": "أمي أو أبي أو معلمتي يشرحون لي أول سؤال.", "ic": "1f468-1f469-1f467"}, {"h": "أكمل وأفرح", "x": "أضع نجمة على ما أنجزته.", "ic": "2b50"}]}, {"t": "ex", "title": "تذكّر", "x": "لا بأس أن أغيّر النشاط إذا لم يعجبني، فاللعب والتعلم يجتمعان."}]$j$::jsonb,array['أطبّق الخطوات واحدة واحدة.','أطلب المساعدة عندما أحتاج.','أفرح بما أنجزته!']::text[],'images/guides/gd-child-activity/cover.webp','files/guides/gd-child-activity.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',220),
('gd-child-stories','child','guide','أفتح القصص وأقرؤها','دليل مصوّر لقراءة القصص خطوة خطوة مع أسئلة ممتعة.',array['a4','a5','a6','g1','g2']::text[],'القصص',array['أتعلّم كيف أفعل ذلك وحدي أو مع أمي أو أبي أو معلمتي.']::text[],'دليل مصوّر قصير. اقرأ الخطوات مع شخص كبير، ثم جرّب بنفسك!',$j$[{"t": "steps", "title": "", "items": [{"h": "أختار قصة", "x": "أنظر إلى الغلاف وأقول: ما رأيي في هذه القصة؟", "ic": "i_book"}, {"h": "أقرأ أو أسمع", "x": "أقرأ بنفسي أو يقرأ معي شخص كبير.", "ic": "1f4d6"}, {"h": "أنظر إلى الصور", "x": "الصور تخبرني بأشياء جميلة عن القصة.", "ic": "1f441"}, {"h": "أسأل وأتخيّل", "x": "ماذا سيحدث بعد ذلك؟ من أحببت في القصة؟", "ic": "1f914"}, {"h": "أحكي القصة بكلماتي", "x": "أحكيها لأمي أو أبي أو دميتي.", "ic": "1f5e3"}]}, {"t": "ex", "title": "تذكّر", "x": "أستطيع أن أقرأ القصة المفضلة أكثر من مرة!"}]$j$::jsonb,array['أطبّق الخطوات واحدة واحدة.','أطلب المساعدة عندما أحتاج.','أفرح بما أنجزته!']::text[],'images/guides/gd-child-stories/cover.webp','files/guides/gd-child-stories.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',230),
('gd-child-cards','child','guide','ألعب بالبطاقات التعليمية','دليل مصوّر لألعاب سهلة بالبطاقات يلعبها الطفل مع أسرته.',array['a4','a5','a6','g1','g2']::text[],'البطاقات',array['أتعلّم كيف أفعل ذلك وحدي أو مع أمي أو أبي أو معلمتي.']::text[],'دليل مصوّر قصير. اقرأ الخطوات مع شخص كبير، ثم جرّب بنفسك!',$j$[{"t": "steps", "title": "", "items": [{"h": "أقصّ البطاقات بحذر", "x": "أطلب من أمي أو أبي أن يساعداني في القص.", "ic": "i_scissors"}, {"h": "أسمّي كل بطاقة", "x": "أنظر إلى الصورة وأقول اسمها.", "ic": "1f5e3"}, {"h": "أجد البطاقة", "x": "أمي تقول: أين الموزة؟ وأنا أشير إليها.", "ic": "1f446"}, {"h": "أطابق البطاقات", "x": "أضع البطاقة الشبيهة بجانب أختها.", "ic": "1f9e9"}, {"h": "أحفظها في علبة", "x": "أضع البطاقات في علبتها لألعب بها غدًا.", "ic": "1f4e6"}]}, {"t": "ex", "title": "تذكّر", "x": "أستعمل المقص بحضور شخص كبير دائمًا."}]$j$::jsonb,array['أطبّق الخطوات واحدة واحدة.','أطلب المساعدة عندما أحتاج.','أفرح بما أنجزته!']::text[],'images/guides/gd-child-cards/cover.webp','files/guides/gd-child-cards.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',240),
('gd-child-worksheets','child','guide','أحلّ ورقة العمل','دليل مصوّر لحل ورقة العمل من القراءة إلى المراجعة.',array['a4','a5','a6','g1','g2']::text[],'أوراق العمل',array['أتعلّم كيف أفعل ذلك وحدي أو مع أمي أو أبي أو معلمتي.']::text[],'دليل مصوّر قصير. اقرأ الخطوات مع شخص كبير، ثم جرّب بنفسك!',$j$[{"t": "steps", "title": "", "items": [{"h": "أجهّز أدواتي", "x": "قلم رصاص وممحاة وألوان.", "ic": "i_pencils"}, {"h": "أقرأ السؤال", "x": "أقرأه مرة، وأسأل إذا لم أفهم.", "ic": "1f4d6"}, {"h": "أفكّر ثم أكتب", "x": "أنظر في المثال ثم أحاول الحل.", "ic": "270f"}, {"h": "أراجع إجابتي", "x": "أنظر مرة أخرى قبل أن أنتهي.", "ic": "1f50d"}, {"h": "أرتاح وأفرح", "x": "أنهيت ورقتي! أستطيع أن أرتاح وألعب.", "ic": "1f604"}]}, {"t": "ex", "title": "تذكّر", "x": "الخطأ ليس مشكلة؛ هو فرصة لأتعلّم."}]$j$::jsonb,array['أطبّق الخطوات واحدة واحدة.','أطلب المساعدة عندما أحتاج.','أفرح بما أنجزته!']::text[],'images/guides/gd-child-worksheets/cover.webp','files/guides/gd-child-worksheets.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',250),
('gd-child-games','child','guide','أستفيد من الألعاب التعليمية','دليل مصوّر يعلّم الطفل كيف يلعب الألعاب التعليمية بوقت مناسب ويتعلم منها.',array['a4','a5','a6','g1','g2']::text[],'الألعاب',array['أتعلّم كيف أفعل ذلك وحدي أو مع أمي أو أبي أو معلمتي.']::text[],'دليل مصوّر قصير. اقرأ الخطوات مع شخص كبير، ثم جرّب بنفسك!',$j$[{"t": "steps", "title": "", "items": [{"h": "أختار لعبة مناسبة", "x": "مع أمي أو أبي أختار لعبة مكتوب عليها عمري.", "ic": "1f3ae"}, {"h": "أحدّد وقت اللعب", "x": "نضع الساعة أو المؤقت: ١٠ أو ١٥ دقيقة.", "ic": "23f3"}, {"h": "ألعب بتركيز", "x": "أقرأ التعليمات وأجرّب أكثر من مرة.", "ic": "1f9e0"}, {"h": "أتعلّم من الخطأ", "x": "إذا أخطأت أحاول من جديد.", "ic": "1f4aa"}, {"h": "أطفئ اللعبة وأرتاح", "x": "أنتقل إلى اللعب الحقيقي أو أشرب ماء.", "ic": "1f4a7"}]}, {"t": "ex", "title": "تذكّر", "x": "اللعب الجميل يكون بوقت محدد ومعه تعلّم وراحة."}]$j$::jsonb,array['أطبّق الخطوات واحدة واحدة.','أطلب المساعدة عندما أحتاج.','أفرح بما أنجزته!']::text[],'images/guides/gd-child-games/cover.webp','files/guides/gd-child-games.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',260),
('gd-age-1-2','parent','age','دليل التعلم من سنة إلى سنتين','إرشادات للتعلم من خلال اللعب والتسمية والحواس والتفاعل اليومي مع الطفل الصغير.',array['a2']::text[],'حسب العمر والمرحلة',array['أن تفهم كيف يتعلم الطفل في هذه السن.','أن تختار أنشطة قصيرة وآمنة.','أن تستعمل الحديث والغناء والحركة كأدوات للتعلم.']::text[],'في هذه السن يتعلم الطفل من العلاقة معك ومن حواسه وحركته. المكتبة هنا أداة بيد الكبار: صور وبطاقات كبيرة ونطق واضح وأغانٍ، دون أي واجبات.',$j$[{"t": "h", "x": "ماذا يميّز هذه المرحلة؟"}, {"t": "table", "head": ["الجانب", "ما تلاحظه غالبًا"], "rows": [["اللغة", "يلتقط كلمات بسيطة ويقلد الأصوات ويشير إلى ما يريد"], ["الحركة", "يمشي ويتسلق ويمسك الأشياء ويرميها ويكرّر"], ["الانتباه", "قصير جدًا، دقائق معدودة لكل شيء"], ["التعلم", "عبر اللمس والتذوق والتجربة والتكرار"]]}, {"t": "h", "x": "أنشطة ومحتوى مناسب"}, {"t": "table", "head": ["النشاط", "لماذا يناسب؟"], "rows": [["بطاقات صور كبيرة (حيوانات، فواكه، أجزاء الجسم)", "تسمّي الأشياء وتثري المفردات"], ["أصوات الحيوانات", "تدرّب النطق والاستماع"], ["كتب وقصص مصوّرة قصيرة", "تنمّي الانتباه والمشاركة"], ["لعب حسي (ماء، رمل، أشياء ملموسة)", "تعلم بالتجربة"], ["أغانٍ وحركات", "تنمّي الإيقاع واللغة"]]}, {"t": "h", "x": "جلسة نموذجية"}, {"t": "steps", "title": "", "items": [{"h": "اجلس بمستوى الطفل", "x": "على الأرض بجانبه ليشعر بالأمان."}, {"h": "اعرض بطاقة واحدة وسمِّها بوضوح", "x": "قل الكلمة ببطء وكرّرها."}, {"h": "اترك له وقتًا ليشير أو يقلّد", "x": "لا تستعجله ولا تصحّح بقسوة."}, {"h": "أضف حركة أو صوتًا", "x": "غنِّ أو قلّد صوت الحيوان."}, {"h": "انهِ الجلسة بعد ٥ إلى ١٠ دقائق", "x": "عندما ينصرف انتباهه، توقّف دون ضغط."}]}, {"t": "tips", "title": "ما الذي أتجنبه؟", "items": ["إجباره على الجلوس أو التكرار.", "استعمال أوراق عمل أو كتابة.", "الاعتماد على الشاشات؛ يُنصح عادةً بتقليلها كثيرًا في هذه السن.", "الأدوات الصغيرة الخطرة؛ راقبه دائمًا."]}, {"t": "ex", "title": "مثال تطبيقي", "x": "أم تحمل ابنتها (١٨ شهرًا) وتعرض بطاقة «قطة»: «هذه قطة، مياو!» ثم تضعها أمامها وتنتظر إن كانت الطفلة تشير إليها، وتختم بأغنية قصيرة عن القطة."}]$j$::jsonb,array['الطفل يتعلم بالعلاقة والحواس والتكرار.','بطاقة واحدة وصوت واضح.','٥ إلى ١٠ دقائق فقط.','لا أوراق عمل ولا ضغط.']::text[],'images/guides/gd-age-1-2/cover.webp','files/guides/gd-age-1-2.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',310),
('gd-age-5-6','parent','age','دليل التعلم من ٥ إلى ٦ سنوات','إرشادات الاستعداد للمدرسة: الحروف والأعداد وتتبّع الخطوط والقصص والمتاهات بمدة جلسة مناسبة.',array['a5','a6']::text[],'حسب العمر والمرحلة',array['أن تهيّئ طفلك لبداية المدرسة بأنشطة مناسبة.','أن تدعم الحروف والأعداد دون ضغط.','أن تدرّب يده على الإمساك بالقلم.']::text[],'هذه مرحلة التهيئة للقراءة والكتابة والعدّ. يحتاج الطفل إلى تدريب ممتع منظم، لكنه ما زال يتعلم باللعب والحركة، فلا تتحول الجلسات إلى مدرسة مبكرة.',$j$[{"t": "h", "x": "ماذا يميّز هذه المرحلة؟"}, {"t": "table", "head": ["الجانب", "ما تلاحظه غالبًا"], "rows": [["اللغة", "يحكي قصصًا ويتعرف إلى أصوات الحروف"], ["الرياضيات", "يعدّ إلى ٢٠ ويقارن ويجمع بالأشياء"], ["اليد", "يتحسن إمساكه بالقلم ويتتبع الخطوط"], ["الانتباه", "١٥ إلى ٢٠ دقيقة مع نشاط ممتع"]]}, {"t": "h", "x": "أنشطة ومحتوى مناسب"}, {"t": "table", "head": ["النشاط", "لماذا يناسب؟"], "rows": [["تتبّع الخطوط والأشكال", "تحضّر لليد للكتابة"], ["بطاقات الحروف والأعداد", "تعرّف أصوات الحروف والعدّ"], ["متاهات سهلة ووصل نقاط", "تنمّي التركيز"], ["قصص وأسئلة فهم", "تنمّي اللغة"], ["أنشطة القص واللصق والفرز", "تنمّي العضلات الدقيقة والمنطق"]]}, {"t": "h", "x": "جلسة نموذجية"}, {"t": "steps", "title": "", "items": [{"h": "سخّن بلعبة أو أغنية", "x": "مثل إيجاد الحرف الذي يبدأ به اسم الطفل."}, {"h": "نفّذ نشاطًا رئيسيًا ١٠ دقائق", "x": "مثل تتبّع حرف أو العدّ بالأشياء."}, {"h": "أدخل لعبة تدعم الفكرة", "x": "بطاقات أو لعبة مطابقة."}, {"h": "راجع بكلمات الطفل", "x": "اسأله: ماذا تعلّمنا؟"}, {"h": "اختم بنشاط حر", "x": "تلوين أو لعب بعد الجلسة."}]}, {"t": "tips", "title": "ما الذي أتجنبه؟", "items": ["إجبار الطفل على الكتابة الطويلة.", "تصحيح كل حرف بالمسطرة الصارمة.", "مقارنته بمن حوله.", "الجلسات الطويلة بلا استراحة."]}, {"t": "ex", "title": "مثال تطبيقي", "x": "مع طفلة (٦ سنوات): جلسة ١٥ دقيقة: لعبة «أين الحرف؟» بالبطاقات، ثم تتبّع الحرف «ب» في ٥ دقائق، ثم قراءة كلمة «بيت» وتلوين الصورة."}]$j$::jsonb,array['تهيئة ممتعة لا مدرسة مبكرة.','نشاط رئيسي قصير ثم لعبة ثم مراجعة.','تتبّع الخطوط والحروف والأعداد.','١٥ إلى ٢٠ دقيقة تكفي.']::text[],'images/guides/gd-age-5-6/cover.webp','files/guides/gd-age-5-6.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',330),
('gd-age-g1-2','parent','age','دليل التعلم للصفين الأول والثاني','إرشادات دعم القراءة والكتابة والحساب في بداية المدرسة: روتين الواجب والمراجعة القصيرة والقراءة اليومية.',array['g1','g2']::text[],'حسب العمر والمرحلة',array['أن تدعم القراءة والكتابة والحساب في بدايتها.','أن تنظّم روتين المراجعة والواجب.','أن تحفّز الطفل على القراءة الحرة.']::text[],'يتحول الطفل في هذه المرحلة من اللعب إلى التعلم المنظم، ويحتاج إلى دعم عاطفي وروتين واضح. الهدف أن يحب المدرسة، فتتقدم مهاراته الأساسية بثبات.',$j$[{"t": "h", "x": "ماذا يميّز هذه المرحلة؟"}, {"t": "table", "head": ["الجانب", "ما تلاحظه غالبًا"], "rows": [["القراءة", "يتهجّأ كلمات ثم يقرأ جملًا قصيرة"], ["الكتابة", "يكتب كلمات وجملًا قصيرة بخط يتحسّن"], ["الحساب", "يجمع ويطرح ضمن ٢٠ ثم ١٠٠ تدريجيًا"], ["الانتباه", "٢٠ إلى ٣٠ دقيقة مع استراحة"]]}, {"t": "h", "x": "أنشطة ومحتوى مناسب"}, {"t": "table", "head": ["النشاط", "لماذا يناسب؟"], "rows": [["قراءة يومية ١٠ إلى ١٥ دقيقة", "تقوّي الطلاقة والمفردات"], ["أوراق عمل قصيرة وفرز وتصنيف", "تطبيق مركّز"], ["خرائط ذهنية وملصقات بسيطة", "تنظم المعلومة"], ["ألعاب حساب وبطاقات", "تثبّت الجمع والطرح"], ["أنشطة كتابة جملة يومية", "تنمّي التعبير"]]}, {"t": "h", "x": "جلسة نموذجية"}, {"t": "steps", "title": "", "items": [{"h": "استراحة بعد المدرسة", "x": "ساعة راحة وطعام قبل الواجب."}, {"h": "راجع الواجب بعد أن يبدأه وحده", "x": "ساعده بتلميح فقط."}, {"h": "نشاط مراجعة قصير ١٠ دقائق", "x": "ورقة أو بطاقات."}, {"h": "قراءة حرة ١٠ دقائق", "x": "يختار كتابه بنفسه."}, {"h": "اختم بسؤال: ما أجمل ما تعلمت اليوم؟", "x": "ثم نوم مبكر."}]}, {"t": "tips", "title": "ما الذي أتجنبه؟", "items": ["إنجاز الواجب بدلًا من الطفل.", "الطلبات الكثيرة في اليوم الواحد.", "التوبيخ عند الخطأ.", "إلغاء وقت اللعب الحر."]}, {"t": "ex", "title": "مثال تطبيقي", "x": "طفل في الصف الأول: بعد غداء وراحة يكتب جملة عن يومه ويقرأ صفحتين من قصة، ثم يلعب لعبة جمع بالبطاقات ١٠ دقائق، وتنتهي الجلسة بنجمة على لوحته."}]$j$::jsonb,array['روتين واضح ولطيف.','استراحة قبل الواجب.','قراءة حرة يومية.','تلميحات لا حلول جاهزة.']::text[],'images/guides/gd-age-g1-2/cover.webp','files/guides/gd-age-g1-2.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',340),
('gd-age-g3-4','parent','age','دليل التعلم للصفين الثالث والرابع','إرشادات دعم الاستقلالية والفهم القرائي والضرب والقسمة والكتابة وتنظيم المذاكرة.',array['g3','g4']::text[],'حسب العمر والمرحلة',array['أن تشجّع استقلالية الطفل في المذاكرة.','أن تدعم الفهم القرائي وجداول الضرب.','أن تساعده على التخطيط والتنظيم.']::text[],'يبدأ الطفل في هذه المرحلة بالاعتماد على نفسه أكثر، لكنه ما زال يحتاج إلى متابعة وتوجيه. ركّز على الفهم لا الحفظ، وعلى مهارات التنظيم والاستعداد للاختبارات.',$j$[{"t": "h", "x": "ماذا يميّز هذه المرحلة؟"}, {"t": "table", "head": ["الجانب", "ما تلاحظه غالبًا"], "rows": [["القراءة", "يقرأ فقرات ويستنتج ويلخّص"], ["الكتابة", "يكتب فقرة قصيرة منظمة"], ["الحساب", "الضرب والقسمة والكسور البسيطة"], ["الاستقلال", "يحتاج لتعلّم تنظيم الوقت والأدوات"]]}, {"t": "h", "x": "أنشطة ومحتوى مناسب"}, {"t": "table", "head": ["النشاط", "لماذا يناسب؟"], "rows": [["أوراق وتدريبات متدرجة", "تثبّت المهارات"], ["ملخصات وخرائط ذهنية", "تنظّم الدرس"], ["جداول الضرب والقسمة", "ترسخ الحقائق الأساسية"], ["قراءة نصوص وكتب أطول", "تنمّي الفهم"], ["اختبارات قصيرة تدريبية", "تعوّد على الاختبار"]]}, {"t": "h", "x": "جلسة نموذجية"}, {"t": "steps", "title": "", "items": [{"h": "خطّط مع الطفل لما سيذاكره", "x": "اكتبا قائمة قصيرة بما يلزم اليوم."}, {"h": "اترك له البداية وحده", "x": "تدخّل عند الحاجة فقط."}, {"h": "راجع الفهم بأسئلة", "x": "اطلب منه أن يشرح لك الدرس بكلماته."}, {"h": "درّب على الجداول بالألعاب", "x": "لعبة ورق أو بطاقات ٥ دقائق يوميًا."}, {"h": "اختم بملخص صغير", "x": "يكتبه الطفل في دفتر مراجعة."}]}, {"t": "tips", "title": "ما الذي أتجنبه؟", "items": ["المذاكرة بدل الطفل أو الجلوس فوق رأسه.", "ربط الحب بالعلامات.", "التركيز على الحفظ دون فهم.", "المقارنة بالأقران."]}, {"t": "ex", "title": "مثال تطبيقي", "x": "طالب في الصف الرابع يستعد لاختبار الكسور: يصنع خريطة ذهنية، ثم يحل ١٠ أسئلة تدريب قصيرة، ويشرح درس الكسور لأبيه في ٣ دقائق ليتأكد من فهمه."}]$j$::jsonb,array['شجّع الاستقلالية وتابع من بعيد.','ركّز على الفهم لا الحفظ.','أنشطة منظمة وملخصات وتدريب قصير.','التنظيم مهارة تُعلَّم.']::text[],'images/guides/gd-age-g3-4/cover.webp','files/guides/gd-age-g3-4.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',350),
('gd-sec-worksheets','parent','section','دليل قسم أوراق العمل','كيف تستفيد من أوراق العمل في المكتبة: اختيار الورقة وطباعتها وتنفيذها ومراجعتها.',array['a5','a6','g1','g2','g3','g4']::text[],'أوراق العمل',array['أن تعرف أنواع أوراق العمل المتاحة.','أن تختار الورقة بحسب المهارة والمستوى.','أن تنفّذ الورقة وتراجعها بفاعلية.']::text[],'أوراق العمل أنشطة مطبوعة تدرّب مهارة محددة، وهي الأنسب للتطبيق بعد الشرح أو اللعب.',$j$[{"t": "h", "x": "ماذا تجد في هذا القسم؟"}, {"t": "table", "head": ["العنصر", "فائدته"], "rows": [["ورقة تدريب", "تكرار مهارة بأسئلة متدرجة"], ["ورقة تلوين وتتبّع", "تدريب اليد للصغار"], ["ورقة تصنيف أو مطابقة", "تنمية التفكير"], ["صفحة إجابات", "للمراجعة السريعة من الكبير"]]}, {"t": "h", "x": "كيف تستفيد منه؟"}, {"t": "steps", "title": "", "items": [{"h": "اختر المهارة والصف", "x": "ثم افتح الورقة وانظر إلى المعاينة."}, {"h": "اطبع بحجم ١٠٠٪", "x": "على ورق A4 دون تصغير، وبالأبيض والأسود إن أردت توفير الحبر."}, {"h": "نفّذ بجلسة قصيرة", "x": "حلّا السؤال الأول معًا ثم أكمل الطفل."}, {"h": "راجع بالإجابات", "x": "افتح صفحة الإجابات بعد أن ينتهي الطفل، ولا تعطه إياها قبل المحاولة."}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "ورقة «جمع وطرح حتى ٢٠» لطفل في الصف الأول: يحلّ ٦ مسائل ثم يراجع مع أبيه، ويلوّن نجمة إذا أصاب ٥ منها."}, {"t": "h", "x": "للمعلمين"}, {"t": "p", "x": "يمكن استعمال الورقة تمهيدًا للدرس أو تدريبًا بعده، ويمكن قص الأوراق إلى بطاقات للعمل في مجموعات."}, {"t": "tips", "title": "نصائح عملية", "items": ["اقرأ العنوان والوصف قبل الطباعة.", "نظّم الأوراق في ملف بحسب المهارة.", "لا تطبع أكثر مما ستستعمله هذا الأسبوع."]}]$j$::jsonb,array['أوراق العمل للتدريب بعد الفهم.','اطبع بحجم ١٠٠٪.','راجع بصفحة الإجابات بعد المحاولة.']::text[],'images/guides/gd-sec-worksheets/cover.webp','files/guides/gd-sec-worksheets.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',410),
('gd-sec-stories','parent','section','دليل قسم القصص التعليمية','كيف تستعمل القصص في البيت والصف: اختيار القصة وقراءتها بالحوار وتنفيذ نشاط بعدها.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'القصص التعليمية',array['أن تعرف خصائص القصص التعليمية.','أن تقرأها بالحوار والتفاعل.','أن تربطها بنشاط بعد القراءة.']::text[],'القصص التعليمية تقدّم القيم والمفاهيم داخل أحداث ممتعة، وتناسب القراءة المشتركة وقبل النوم.',$j$[{"t": "h", "x": "ماذا تجد في هذا القسم؟"}, {"t": "table", "head": ["العنصر", "فائدته"], "rows": [["قصة بصور", "جذب انتباه الصغار"], ["أسئلة فهم", "تقويم سريع للمعنى"], ["قيم ومهارات", "التعاون والصدق والنظافة وغيرها"], ["مفردات جديدة", "إثراء لغة الطفل"]]}, {"t": "h", "x": "كيف تستفيد منه؟"}, {"t": "steps", "title": "", "items": [{"h": "اختر قصة بحسب العمر", "x": "والموضوع الذي يهمّ الطفل."}, {"h": "اقرأ مرة بالتفاعل", "x": "قف عند الصور واسأل ماذا سيحدث."}, {"h": "اطرح سؤالين بعد القراءة", "x": "سؤال عن الأحداث وسؤال عن الرأي."}, {"h": "نفّذ نشاطًا قصيرًا", "x": "رسم، تمثيل، أو إعادة ترتيب الأحداث."}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "بعد قصة عن النظافة: يرسم الطفل ثلاث عادات نظيفة ثم يضعها على لوحة العادات اليومية."}, {"t": "h", "x": "للمعلمين"}, {"t": "p", "x": "تُستعمل القصة بوصفها تمهيدًا لدرس، أو نصًا للقراءة الجهرية، أو منطلقًا للكتابة التعبيرية."}, {"t": "tips", "title": "نصائح عملية", "items": ["اجعل الطفل يختار القصة أحيانًا.", "كرّر القصة المفضلة.", "لا تحوّل الحوار إلى اختبار."]}]$j$::jsonb,array['القصة وسيلة حوار.','سؤالان بعد القراءة كافيان.','نشاط قصير يثبّت الفكرة.']::text[],'images/guides/gd-sec-stories/cover.webp','files/guides/gd-sec-stories.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',420),
('gd-sec-cards','parent','section','دليل قسم البطاقات التعليمية','كيف تختار البطاقات وتحضّرها وتلعب بها في البيت والصف.',array['a2','a3','a4','a5','a6','g1','g2']::text[],'البطاقات التعليمية',array['أن تعرف أنواع البطاقات.','أن تحضّر البطاقات للعب.','أن تلعب بها ألعابًا مناسبة للعمر.']::text[],'البطاقات صور وكلمات ومفاهيم تُستعمل في التسمية والمطابقة والتصنيف والمراجعة.',$j$[{"t": "h", "x": "ماذا تجد في هذا القسم؟"}, {"t": "table", "head": ["العنصر", "فائدته"], "rows": [["بطاقات صور", "تسمية الأشياء وإثراء المفردات"], ["بطاقات حروف وأعداد", "التهيئة للقراءة والعدّ"], ["بطاقات مفاهيم", "مفاهيم الرياضيات والعلوم"], ["بطاقات كلمات", "القراءة المبكرة"]]}, {"t": "h", "x": "كيف تستفيد منه؟"}, {"t": "steps", "title": "", "items": [{"h": "اختر الفئة العمرية", "x": "ثم افتح مجموعة البطاقات وعاينها."}, {"h": "اطبع وقصّ", "x": "ورق متين أفضل، ويمكن تغليفها."}, {"h": "ابدأ بعدد قليل", "x": "٣ إلى ٥ بطاقات ثم زد بالتدريج."}, {"h": "العب لعبة قصيرة", "x": "أين البطاقة؟ المطابقة؟ المفقودة؟"}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "مجموعة بطاقات الحيوانات: يسمّيها الطفل ثم يصنّفها إلى «تعيش في البيت» و«تعيش في الغابة»."}, {"t": "h", "x": "للمعلمين"}, {"t": "p", "x": "تصلح كمحطات في الصف، أو كتمهيد في بداية الدرس، أو كبطاقات خروج سريعة."}, {"t": "tips", "title": "نصائح عملية", "items": ["اجمع كل مجموعة في ظرف.", "ضع رقمًا أو لونًا على كل مجموعة.", "لا تقدّم كل البطاقات مرة واحدة."]}]$j$::jsonb,array['ابدأ بعدد قليل.','اللعب أهم من الحفظ.','نظّم المجموعات لإعادة الاستعمال.']::text[],'images/guides/gd-sec-cards/cover.webp','files/guides/gd-sec-cards.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',430),
('gd-sec-activities','parent','section','دليل قسم الأنشطة المنزلية','كيف تنفّذ الأنشطة المنزلية بأدوات بسيطة وتحوّلها إلى وقت أسري ممتع.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'الأنشطة المنزلية',array['أن تعرف نوعية الأنشطة المنزلية.','أن تجهّز أدواتها وتنفّذها بأمان.','أن تقيّم أثر النشاط على الطفل.']::text[],'الأنشطة المنزلية تجارب وأعمال يدوية وألعاب بسيطة بأدوات متوفرة غالبًا في البيت.',$j$[{"t": "h", "x": "ماذا تجد في هذا القسم؟"}, {"t": "table", "head": ["العنصر", "فائدته"], "rows": [["نشاط حسي أو علمي", "تجربة بسيطة وملاحظة"], ["نشاط فني", "رسم وقص ولصق"], ["نشاط رياضي (حساب)", "عدّ وقياس وتصنيف"], ["نشاط لغوي", "ألعاب كلمات وحروف"]]}, {"t": "h", "x": "كيف تستفيد منه؟"}, {"t": "steps", "title": "", "items": [{"h": "اقرأ النشاط كاملًا قبل البدء", "x": "وتأكد من الأدوات والزمن."}, {"h": "جهّز المكان والأدوات", "x": "على طاولة واحدة، وأبعد ما يشتت."}, {"h": "نفّذ مع الطفل", "x": "اترك له أكبر قدر من التنفيذ."}, {"h": "تحدّثا عن النتيجة", "x": "ماذا لاحظنا؟ ماذا تعلّمنا؟"}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "نشاط «إنبات بذرة»: تضع الأسرة بذرة في قطنة مبللة، ويرسم الطفل ما يلاحظه كل يوم لمدة أسبوع."}, {"t": "h", "x": "للمعلمين"}, {"t": "p", "x": "الأنشطة المنزلية مصدر لأفكار واجبات عملية أو مشاريع صغيرة."}, {"t": "tips", "title": "نصائح عملية", "items": ["راقب سلامة الطفل في أي نشاط فيه مقص أو ماء أو حرارة.", "قدّر زمن النشاط قبل البدء.", "صوّر النتيجة واحتفظ بها في ملف إنجازات."]}]$j$::jsonb,array['اقرأ النشاط قبل البدء.','اترك التنفيذ للطفل.','تحدّثا عما لاحظتما.']::text[],'images/guides/gd-sec-activities/cover.webp','files/guides/gd-sec-activities.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',440),
('gd-sec-summaries','parent','section','دليل قسم الملخصات والمراجعات','كيف تستعمل الملخصات للمراجعة السريعة وتربطها بالتدريب والاختبارات.',array['g1','g2','g3','g4']::text[],'الملخصات والمراجعات',array['أن تعرف ما تقدّمه الملخصات.','أن تستعملها قبل الاختبار وبعد الدرس.','أن تدمجها بالتدريب والأسئلة.']::text[],'الملخصات تقدّم الفكرة الأساسية للدرس بإيجاز، وتفيد في المراجعة وتثبيت الفهم، لكنها لا تغني عن الدرس نفسه.',$j$[{"t": "h", "x": "ماذا تجد في هذا القسم؟"}, {"t": "table", "head": ["العنصر", "فائدته"], "rows": [["ملخص الدرس", "الأفكار الرئيسة بإيجاز"], ["نقاط التذكّر", "قواعد وقوانين مختصرة"], ["أسئلة مراجعة", "اختبار الفهم"]]}, {"t": "h", "x": "كيف تستفيد منه؟"}, {"t": "steps", "title": "", "items": [{"h": "اقرأ الدرس أولًا", "x": "الملخص لا يغني عنه."}, {"h": "اقرأ الملخص بصوت مرتفع", "x": "ثم شرحه بكلمات الطفل."}, {"h": "جرّب أسئلة المراجعة", "x": "ثم راجع الأجزاء التي أخطأ فيها."}, {"h": "أعد الملخص بعد أيام", "x": "التكرار المتباعد يثبّت المعلومة."}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "قبل اختبار الكسور في الصف الرابع: يقرأ الطالب الملخص ثم يحلّ ١٠ أسئلة ويكتب في دفتره ما أخطأ فيه."}, {"t": "h", "x": "للمعلمين"}, {"t": "p", "x": "يصلح الملخص لتلخيص نهاية الوحدة أو لتوزيعه كمرجع سريع على الطلاب."}, {"t": "tips", "title": "نصائح عملية", "items": ["اطلب من الطفل أن يصنع ملخصه الخاص بعد قراءة الملخص.", "وزّع المراجعة على عدة أيام.", "لا تستعمل الملخص بديلًا عن الفهم."]}]$j$::jsonb,array['الملخص يدعم الفهم ولا يحلّ محلّه.','اجمع الملخص مع التدريب.','راجع على أيام متباعدة.']::text[],'images/guides/gd-sec-summaries/cover.webp','files/guides/gd-sec-summaries.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',450),
('gd-sec-tests','parent','section','دليل قسم الاختبارات وبنوك الأسئلة','كيف تستعمل الاختبارات وبنك الأسئلة للتدريب وقياس الفهم دون ضغط.',array['g1','g2','g3','g4']::text[],'الاختبارات وبنوك الأسئلة',array['أن تعرف الغرض من الاختبارات التدريبية.','أن تنفّذ اختبارًا قصيرًا مع الطفل.','أن تتعامل مع النتيجة بإيجابية.']::text[],'الاختبارات في المكتبة أدوات تدريب وتشخيص، لا امتحانات رسمية. هدفها أن يعرف الطفل ما أتقنه وما يحتاج إلى مراجعة.',$j$[{"t": "h", "x": "ماذا تجد في هذا القسم؟"}, {"t": "table", "head": ["العنصر", "فائدته"], "rows": [["اختبار قصير", "قياس فهم درس أو وحدة"], ["بنك أسئلة", "أسئلة متنوعة بحسب الصف والمادة"], ["نتيجة وإجابات", "معرفة الأخطاء وتصحيحها"]]}, {"t": "h", "x": "كيف تستفيد منه؟"}, {"t": "steps", "title": "", "items": [{"h": "اختر الصف والمادة", "x": "ثم اختر اختبارًا قصيرًا."}, {"h": "أجواء هادئة", "x": "بلا ضغط وبدون مقارنة."}, {"h": "اتركه يجيب وحده", "x": "ثم راجعا الإجابات معًا."}, {"h": "خطّط للمراجعة", "x": "الأسئلة التي أخطأ فيها تحدد ما يحتاج إلى تدريب."}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "اختبار «الضرب» للصف الثالث بـ ١٠ أسئلة: بعد النتيجة يختار الطفل جدولين ليراجعهما بالبطاقات."}, {"t": "h", "x": "للمعلمين"}, {"t": "p", "x": "يمكن استعمال الأسئلة كاختبارات قصيرة أو بطاقات خروج، وتحليل الأخطاء لتحديد نقاط الدعم."}, {"t": "tips", "title": "نصائح عملية", "items": ["لا تربط النتيجة بالمكافأة أو العقاب.", "اجعل الاختبار بعد المراجعة لا قبلها.", "كرّر الاختبار بعد أسبوع لقياس التقدم."]}]$j$::jsonb,array['اختبار تدريبي لا حكم على الطفل.','راجع الأخطاء مع الطفل.','خطّط للتدريب حسب النتيجة.']::text[],'images/guides/gd-sec-tests/cover.webp','files/guides/gd-sec-tests.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',460),
('gd-sec-media','parent','section','دليل قسم الوسائل التعليمية','كيف تعرض الخرائط الذهنية والملصقات واللوحات والعروض وتحمّلها وتطبعها وتستعملها في الشرح.',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],'الوسائل التعليمية',array['أن تعرف أنواع الوسائل في القسم.','أن تستعمل العارض للتكبير والتحميل والطباعة.','أن تدمج الوسيلة في الشرح.']::text[],'قسم الوسائل التعليمية فيه خرائط ذهنية وعروض وملصقات ولوحات وجداول وإنفوجرافيك وبطاقات وأنشطة للطباعة، ويمكن عرضها وتكبيرها وتحميلها وطباعتها.',$j$[{"t": "h", "x": "ماذا تجد في هذا القسم؟"}, {"t": "table", "head": ["العنصر", "فائدته"], "rows": [["خريطة ذهنية", "تلخيص وربط المفاهيم"], ["ملصق", "معلومة أو قاعدة مرجعية"], ["لوحة", "متابعة يومية أو أسبوعية"], ["عرض", "شرح متسلسل"], ["ورقة للطباعة", "نشاط قابل للإنجاز باليد"]]}, {"t": "h", "x": "كيف تستفيد منه؟"}, {"t": "steps", "title": "", "items": [{"h": "اختر النوع والعمر أو الصف", "x": "من الفلاتر أعلى الصفحة."}, {"h": "افتح العارض", "x": "تنقّل بين الصفحات وكبّر الصورة عند الحاجة."}, {"h": "حمّل PDF أو اطبع", "x": "يوجد أيضًا PDF أبيض وأسود لتوفير الحبر."}, {"h": "علّق أو اعرض", "x": "ضعها في مكان مرئي أو اعرضها على الشاشة."}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "يطبع أب ملصق «أيام الأسبوع» ويعلّقه عند طاولة الدراسة، ويسأل ابنه كل صباح: ما اليوم؟ وما اليوم الذي يليه؟"}, {"t": "h", "x": "للمعلمين"}, {"t": "p", "x": "يمكن تعليق الملصقات وتحديث اللوحات يوميًا مع الطلاب."}, {"t": "tips", "title": "نصائح عملية", "items": ["للتحميل أبيض وأسود اختر «PDF أبيض وأسود».", "اطبع بحجم ١٠٠٪.", "اختر وسيلة واحدة لكل مفهوم."]}]$j$::jsonb,array['العارض يتيح التكبير والتحميل والطباعة.','وسيلة واحدة لكل فكرة.','علّقها في مكان واضح.']::text[],'images/guides/gd-sec-media/cover.webp','files/guides/gd-sec-media.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',470),
('gd-sec-printables','parent','section','دليل قسم الملفات القابلة للطباعة','نصائح الطباعة والتحضير والتخزين لتستفيد من الملفات القابلة للطباعة بجودة وتوفير.',array['a3','a4','a5','a6','g1','g2','g3','g4']::text[],'الملفات القابلة للطباعة',array['أن تطبع الملفات بجودة وحجم صحيحين.','أن توفّر الحبر والورق.','أن تنظّم الملفات المطبوعة.']::text[],'الملفات القابلة للطباعة تحتاج إلى إعداد بسيط ليخرج الناتج واضحًا ومناسبًا: حجم الورق، النسخة الملوّنة أو الأبيض والأسود، والتخزين.',$j$[{"t": "h", "x": "ماذا تجد في هذا القسم؟"}, {"t": "table", "head": ["العنصر", "فائدته"], "rows": [["PDF ملوّن", "للعرض والاستعمال الجذاب"], ["PDF أبيض وأسود", "لتوفير الحبر والتلوين اليدوي"], ["صفحة إجابات", "للكبير فقط عند الحاجة"]]}, {"t": "h", "x": "كيف تستفيد منه؟"}, {"t": "steps", "title": "", "items": [{"h": "افتح الملف وراجع عدد الصفحات", "x": "اطبع الصفحات المطلوبة فقط."}, {"h": "اختر حجم ١٠٠٪ وورق A4", "x": "ولا تفعّل «ملاءمة الصفحة» أو التصغير."}, {"h": "اختر الأبيض والأسود عند الحاجة", "x": "للأنشطة التي سيلوّنها الطفل."}, {"h": "اقصّ وغلّف وخزّن", "x": "أدوات صغيرة ملونة لاستعمال متكرر."}]}, {"t": "ex", "title": "مثال تطبيقي", "x": "أم تطبع «متاهة سهلة» بنسختين: واحدة ملونة للاحتفاظ بها والأخرى بالأبيض والأسود لتكرار اللعب، وتحتفظ بصفحة الحل منفصلة."}, {"t": "h", "x": "للمعلمين"}, {"t": "p", "x": "اطبع بعدد الطلاب مع هامش، واحتفظ بنسخة معلّم كاملة."}, {"t": "tips", "title": "نصائح عملية", "items": ["اختبر الطباعة بصفحة واحدة أولًا.", "استعمل الوجهين عند الأنشطة التي تتحمّل ذلك.", "خزّن المطبوعات في ملفات بحسب الموضوع."]}]$j$::jsonb,array['حجم ١٠٠٪ وورق A4.','استعمل الأبيض والأسود لتوفير الحبر.','جرّب صفحة واحدة قبل الطباعة الكاملة.']::text[],'images/guides/gd-sec-printables/cover.webp','files/guides/gd-sec-printables.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. ','published',480),
('gd-tpl-home-activity','parent','template','نموذج تنظيم نشاط تعليمي منزلي','نموذج لتخطيط نشاط منزلي: الهدف والأدوات والخطوات والزمن والتقييم.',array['a4','a5','a6','g1','g2','g3','g4']::text[],'نماذج للأسرة',array['أن تستعمل النموذج مطبوعًا وتعبّئه بخط اليد.']::text[],'اطبع هذا النموذج وعبّئه. خطّط النشاط قبل البدء، ثم سجّل ما جرى بعد أن تنتهي.',$j$[{"t": "h", "x": "بيانات النشاط"}, {"t": "form", "title": "", "fields": ["اسم الطفل:", "التاريخ:", "اسم النشاط:", "الهدف (ماذا سيتعلم؟):", "المدة المتوقعة:"], "checks": [], "grid": null, "lines": 0}, {"t": "h", "x": "الأدوات والتحضير"}, {"t": "form", "title": "", "fields": [], "checks": ["الأدوات جاهزة", "المكان مرتّب", "الطفل مرتاح وغير جائع"], "grid": null, "lines": 2}, {"t": "h", "x": "الخطوات"}, {"t": "form", "title": "", "fields": [], "checks": [], "grid": {"head": ["الخطوة", "ماذا سأفعل؟", "المدة"], "rows": 4}, "lines": 0}, {"t": "h", "x": "بعد النشاط"}, {"t": "form", "title": "", "fields": ["ما الذي نجح؟", "ما الذي أحتاج لتغييره؟", "تقييم الطفل (نجمة / وجه مبتسم):"], "checks": [], "grid": null, "lines": 0}]$j$::jsonb,array['اطبع النموذج بحجم ١٠٠٪ على ورق A4.','عبّئه بقلم رصاص ليسهل التعديل.','احتفظ بالنماذج المكتملة في ملف للمتابعة.']::text[],'images/guides/gd-tpl-home-activity/cover.webp','files/guides/gd-tpl-home-activity.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. نموذج قابل للتعبئة والطباعة (يُطبع بحجم ١٠٠٪ على ورق A4).','published',510),
('gd-tpl-skill-tracking','parent','template','نموذج متابعة تعلّم مهارة جديدة','نموذج لتسجيل تقدم الطفل في مهارة واحدة خلال أسبوعين: المحاولات والمستوى والخطوة التالية.',array['a4','a5','a6','g1','g2','g3','g4']::text[],'نماذج للأسرة',array['أن تستعمل النموذج مطبوعًا وتعبّئه بخط اليد.']::text[],'اطبع هذا النموذج وعبّئه. اكتب سطرًا قصيرًا بعد كل جلسة، وراجع النموذج بعد أسبوعين.',$j$[{"t": "h", "x": "المهارة"}, {"t": "form", "title": "", "fields": ["اسم الطفل:", "المهارة (مثال: تتبّع الحرف ب):", "تاريخ البدء:"], "checks": [], "grid": null, "lines": 0}, {"t": "h", "x": "سجل المحاولات"}, {"t": "form", "title": "", "fields": [], "checks": [], "grid": {"head": ["التاريخ", "النشاط المستعمل", "المستوى (يحتاج مساعدة / يتقدّم / متمكّن)", "ملاحظة"], "rows": 7}, "lines": 0}, {"t": "h", "x": "تقييم نهاية الأسبوعين"}, {"t": "form", "title": "", "fields": ["ما الذي تحسّن؟", "ما الذي ما زال يحتاج وقتًا؟", "الخطوة التالية:"], "checks": [], "grid": null, "lines": 0}]$j$::jsonb,array['اطبع النموذج بحجم ١٠٠٪ على ورق A4.','عبّئه بقلم رصاص ليسهل التعديل.','احتفظ بالنماذج المكتملة في ملف للمتابعة.']::text[],'images/guides/gd-tpl-skill-tracking/cover.webp','files/guides/gd-tpl-skill-tracking.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. نموذج قابل للتعبئة والطباعة (يُطبع بحجم ١٠٠٪ على ورق A4).','published',520),
('gd-tpl-story','parent','template','نموذج استخدام قصة تعليمية','نموذج لتخطيط قراءة قصة: قبل القراءة وأثناءها وبعدها مع نشاط ختامي وتأمل.',array['a4','a5','a6','g1','g2','g3','g4']::text[],'نماذج للأسرة',array['أن تستعمل النموذج مطبوعًا وتعبّئه بخط اليد.']::text[],'اطبع هذا النموذج وعبّئه. جهّز سؤالين قبل القراءة وسجّل ما قاله الطفل بعدها.',$j$[{"t": "h", "x": "عن القصة"}, {"t": "form", "title": "", "fields": ["اسم الطفل:", "عنوان القصة:", "الفكرة أو القيمة الرئيسة:", "كلمات جديدة (٣ كلمات):"], "checks": [], "grid": null, "lines": 0}, {"t": "h", "x": "قبل القراءة"}, {"t": "form", "title": "", "fields": ["سؤال التوقّع (عمّ تتحدث القصة؟):", "إجابة الطفل:"], "checks": [], "grid": null, "lines": 0}, {"t": "h", "x": "بعد القراءة"}, {"t": "form", "title": "", "fields": ["سؤال عن الأحداث:", "سؤال عن الرأي (لماذا؟ ماذا كنت ستفعل؟):", "نشاط ختامي (رسم / تمثيل / كتابة جملة):"], "checks": [], "grid": null, "lines": 3}]$j$::jsonb,array['اطبع النموذج بحجم ١٠٠٪ على ورق A4.','عبّئه بقلم رصاص ليسهل التعديل.','احتفظ بالنماذج المكتملة في ملف للمتابعة.']::text[],'images/guides/gd-tpl-story/cover.webp','files/guides/gd-tpl-story.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. نموذج قابل للتعبئة والطباعة (يُطبع بحجم ١٠٠٪ على ورق A4).','published',530),
