('gd-tpl-short-session','parent','template','نموذج تنظيم جلسة تعلّم قصيرة','خطة جلسة من ٢٠ دقيقة بأربع محطات: تسخين ونشاط رئيس ولعبة ومراجعة.',array['a4','a5','a6','g1','g2','g3','g4']::text[],'نماذج للأسرة',array['أن تستعمل النموذج مطبوعًا وتعبّئه بخط اليد.']::text[],'اطبع هذا النموذج وعبّئه. اكتب محطة التسخين أولًا ثم النشاط الرئيس واللعبة والمراجعة.',$j$[{"t": "h", "x": "بيانات الجلسة"}, {"t": "form", "title": "", "fields": ["اسم الطفل:", "التاريخ والوقت:", "هدف الجلسة:"], "checks": [], "grid": null, "lines": 0}, {"t": "h", "x": "محطات الجلسة"}, {"t": "form", "title": "", "fields": [], "checks": [], "grid": {"head": ["المحطة", "ماذا سنفعل؟", "الزمن", "تم؟"], "rows": 4}, "lines": 0}, {"t": "h", "x": "بعد الجلسة"}, {"t": "form", "title": "", "fields": ["ما أجمل ما حدث؟", "ما الذي سأغيّره في الجلسة القادمة؟"], "checks": ["انتهينا في الوقت", "استمتع الطفل بالنشاط"], "grid": null, "lines": 0}]$j$::jsonb,array['اطبع النموذج بحجم ١٠٠٪ على ورق A4.','عبّئه بقلم رصاص ليسهل التعديل.','احتفظ بالنماذج المكتملة في ملف للمتابعة.']::text[],'images/guides/gd-tpl-short-session/cover.webp','files/guides/gd-tpl-short-session.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. نموذج قابل للتعبئة والطباعة (يُطبع بحجم ١٠٠٪ على ورق A4).','published',550),
('gd-tpl-activity-tracker','parent','template','نموذج متابعة الأنشطة المكتملة','جدول لتسجيل الأنشطة التي أنجزها الطفل خلال شهر مع تاريخها وتقييمه ونجومه.',array['a4','a5','a6','g1','g2','g3','g4']::text[],'نماذج للأسرة',array['أن تستعمل النموذج مطبوعًا وتعبّئه بخط اليد.']::text[],'اطبع هذا النموذج وعبّئه. سجّل كل نشاط تنجزه، ثم راجع الجدول آخر الشهر.',$j$[{"t": "h", "x": "بيانات الشهر"}, {"t": "form", "title": "", "fields": ["اسم الطفل:", "الشهر:", "هدف الشهر:"], "checks": [], "grid": null, "lines": 0}, {"t": "h", "x": "سجل الأنشطة"}, {"t": "form", "title": "", "fields": [], "checks": [], "grid": {"head": ["التاريخ", "النشاط أو الورقة", "القسم", "تقييم الطفل (نجمة)", "ملاحظة"], "rows": 12}, "lines": 0}, {"t": "h", "x": "نهاية الشهر"}, {"t": "form", "title": "", "fields": ["عدد الأنشطة المكتملة:", "أفضل نشاط عند الطفل:", "هدف الشهر القادم:"], "checks": [], "grid": null, "lines": 0}]$j$::jsonb,array['اطبع النموذج بحجم ١٠٠٪ على ورق A4.','عبّئه بقلم رصاص ليسهل التعديل.','احتفظ بالنماذج المكتملة في ملف للمتابعة.']::text[],'images/guides/gd-tpl-activity-tracker/cover.webp','files/guides/gd-tpl-activity-tracker.pdf','محتوى أصلي من إعداد زاد؛ كُتب برمجيًا ولم يراجعه مختص تربوي أو جهة تعليمية بعد، وهو إرشادات عامة للاستئناس. نموذج قابل للتعبئة والطباعة (يُطبع بحجم ١٠٠٪ على ورق A4).','published',560)
